INSERT INTO `about_us` VALUES
(1,'Our Roots. Our Faith. Our Future.','[493,494,464,465]','Welcome to Malayalam University, a premier non-profit religious institution based in Florida, USA. Established under the religious exemption guidelines of the Florida Commission for Independent Education, our university serves as a global bridge between the ancient traditions of Kerala, India, and the vibrant Malayali diaspora in the United States and beyond.','[{\"point\":\"Promotion of language, culture, and interdisciplinary studies\"}]','Our Mission','<p data-start=\"3566\" data-end=\"3871\"><span id=\"docs-internal-guid-9305a42d-7fff-ed10-9a2f-a2a7354efa39\" style=\"\"><span style=\"font-size: 12pt; font-family: Arial, sans-serif; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; vertical-align: baseline; white-space-collapse: preserve;\">The mission of Malayalam University is to </span><span style=\"font-size: 12pt; font-family: Arial, sans-serif; font-weight: 700; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; vertical-align: baseline; white-space-collapse: preserve;\">inculcate the spiritual doctrine, liturgical traditions, and ecclesiastical history</span><span style=\"font-size: 12pt; font-family: Arial, sans-serif; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; vertical-align: baseline; white-space-collapse: preserve;\"> of the Mar Thoma Syrian Christian heritage. As a non-profit religious institution, we are dedicated to the </span><span style=\"font-size: 12pt; font-family: Arial, sans-serif; font-weight: 700; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; vertical-align: baseline; white-space-collapse: preserve;\">training of laypersons and religious professionals</span><span style=\"font-size: 12pt; font-family: Arial, sans-serif; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; vertical-align: baseline; white-space-collapse: preserve;\"> in the sacred customs of the St. Thomas Christians of Kerala. Our primary objective is to ensure that the 2,000-year-old faith and cultural legacy of the Nasrani community are preserved and transmitted to future generations through </span><span style=\"font-size: 12pt; font-family: Arial, sans-serif; font-weight: 700; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; vertical-align: baseline; white-space-collapse: preserve;\">specialized religious education</span><span style=\"font-size: 12pt; font-family: Arial, sans-serif; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; vertical-align: baseline; white-space-collapse: preserve;\"> and spiritual formation.</span></span></p>','437','Our Vision','<p data-start=\"4308\" data-end=\"4614\"><span id=\"docs-internal-guid-75a7e7e6-7fff-41c0-25a9-f3d8ffe52176\"><span style=\"font-size: 12pt; font-family: Arial, sans-serif; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; vertical-align: baseline; white-space-collapse: preserve;\">Our vision is to become the global center for the </span><span style=\"font-size: 12pt; font-family: Arial, sans-serif; font-weight: 700; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; vertical-align: baseline; white-space-collapse: preserve;\">preservation of Mar Thoma Christian identity</span><span style=\"font-size: 12pt; font-family: Arial, sans-serif; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; vertical-align: baseline; white-space-collapse: preserve;\">, fostering a community of scholars and practitioners who are deeply rooted in their ancestral faith. We strive to empower the Kerala diaspora and international students to serve as </span><span style=\"font-size: 12pt; font-family: Arial, sans-serif; font-weight: 700; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; vertical-align: baseline; white-space-collapse: preserve;\">stewards of our religious heritage</span><span style=\"font-size: 12pt; font-family: Arial, sans-serif; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; vertical-align: baseline; white-space-collapse: preserve;\">, bridging the ancient traditions of the Malabar Coast with the modern world through a commitment to theological excellence and spiritual continuity.</span></span></p>','460','Our Goal','<p>At Studylifter, our goal is to empower students in their pursuit of global education. We are dedicated to providing personalized guidance, resources, and support at every step of the study abroad process. Our goal is to ensure that each student feels confident and well-prepared to embark on their educational journey. We believe that every student deserves access to high-quality education and the opportunity to experience diverse cultures. By partnering with top universities and leveraging our expertise,</p>','461','[{\"name\":\"Excellence in Higher Education Award\",\"image\":\"499\"},{\"name\":\"Excellence in Higher Education Award\",\"image\":\"500\"}]','[{\"year\":\"2026\",\"title\":\"stablishment of Malayalam University\",\"description\":\"Malayalam University was established with the vision of strengthening higher education and research in language, culture, and humanities while fostering academic innovation.\",\"image\":\"442\"}]','2024-11-02 22:35:43','2026-01-21 05:50:32',NULL);
