(8,'Biblical-Studies-at-the-University-An-Interdisciplinary-Academic-Journey','Biblical Studies at the University: An Interdisciplinary Academic Journey','397','<p data-start=\"1091\" data-end=\"1397\">The University’s Biblical Studies offerings are designed to provide students with a <strong data-start=\"1175\" data-end=\"1242\">critical and interdisciplinary understanding of religious texts</strong>. Rather than focusing solely on devotional reading, the program examines scripture as literature shaped by historical, cultural, and philosophical forces.</p><p data-start=\"1399\" data-end=\"1671\">Students engage with multiple academic perspectives, including textual criticism, archaeology, ethics, and historical analysis. This approach enables learners to understand how belief systems evolved over time and how religious ideas continue to influence societies today.</p><p>\r\n\r\n</p><p data-start=\"1673\" data-end=\"1835\">By fostering analytical thinking and scholarly inquiry, the University prepares students for careers in education, research, cultural studies, and public service.</p>','Biblical Studies Program | Academic Excellence at the University','396','biblical studies, religious studies, theology program, humanities education, university courses','2026-01-15 11:44:00','Discover how the University approaches Biblical Studies through history, archaeology, philosophy, and critical scholarship.',59,8,3,19,'2026-01-15 12:46:56','2026-01-15 12:58:15',NULL),
(9,'Bible-Courses','Bible Courses','471','<p data-start=\"956\" data-end=\"1027\">An introduction to the Bible Courses department and its academic focus.</p>','An introduction to the Bible Courses department and its academic focus.','470','Bible Courses','2026-01-15 23:57:00','Bible Courses',59,8,1,19,'2026-01-15 12:58:05','2026-01-15 14:31:31',NULL),
(10,'Performing-Arts','Performing Arts','469','<p>Where discipline, creativity, and tradition come alive.</p>','Where discipline, creativity, and tradition come alive.','468','Performing Arts','2026-01-15 23:59:00','Performing Arts',59,9,1,19,'2026-01-15 12:59:42','2026-01-15 14:30:57',NULL),
(11,'Certification-Programs','Certification Programs','467','<p>Focused learning for practical and academic growth.</p>','Focused learning for practical and academic growth.','466','Certification Programs','2026-01-14 23:59:00','Certification Programs',59,9,1,19,'2026-01-15 13:01:33','2026-01-15 14:30:31',NULL);
