INSERT INTO `courses` VALUES
(9,1,2,6,19,NULL,NULL,'Basic knowledge of Church History','From Elohim to Abba: A Historical, Linguistic, and Christological Investigation',NULL,NULL,'Basic-knowledge-of-Church-History','300',2,'D9b9h5mCgAc',42,3.00,'Basic knowledge of Church',899.00,'[{\"name\":\"Critical Training\",\"value\":\"Advanced biblical and theological analysis\"},{\"name\":\"Bilingual Study\",\"value\":\"Malayalam & English\"}]','2026-01-31','This seminar provides a forensic, historical, and linguistic investigation into the evolution of divine nomenclature in the biblical text. We move from the Bronze Age \'El\' to the nationalistic \'Yahweh\' of the iron age, concluding with the Christological \'Father.\' The course investigates the \"Alienation Hypothesis\": Did Jesus restore a universal, pre-redactional truth that was suppressed by post-exilic religious authorities?','[{\"title\":\"Philological Mastery\",\"text\":\"Distinguish between $Elohim$, $YHWH$, and $Pater$ in original contexts.\"},{\"title\":\"Redactional Analysis\",\"text\":\"Identify the 5th-century BCE motives of the Ezra group in merging divine attributes.\"},{\"title\":\"Cross-Cultural Synthesis:\",\"text\":\"Map the influence of Persian (Zoroastrian) dualism and Mesopotamian science on Jewish theology.\"},{\"title\":\"Christological Critique:\",\"text\":\"Evaluate Jesus\\u2019 rejection of Temple hierarchies and his use of \\\"Abba\\\" as a corrective to nationalistic Yahwism.\"}]','[{\"question\":\"Who can enroll in this course?\",\"answer\":\"Graduate students, theology scholars, clergy, and advanced learners with interest in biblical history and linguistics.\"},{\"question\":\"Is prior knowledge of Hebrew or Greek required?\",\"answer\":\"Is prior knowledge of Hebrew or Greek required?\"},{\"question\":\"What languages can assignments be submitted in?\",\"answer\":\"Malayalam or English (SBL academic style).\"},{\"question\":\"Is this course fully online?\",\"answer\":\"Yes. All lectures, readings, and Socratic seminars are conducted online\"},{\"question\":\"What is the final assessment?\",\"answer\":\"A 20-page research-based synthesis paper defending a theological or historical thesis.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-12 23:51:20','2026-01-19 00:05:38'),
(10,3,2,6,19,NULL,NULL,'Introduction to Biblical Literature','Understanding the Bible as History, Literature, and Faith',NULL,NULL,'Introduction-to-Biblical-Literature','332',2,'Ne_uxf61zOE',1,3.00,NULL,100.00,'[{\"name\":\"Academic Foundation\",\"value\":\"Strong foundation in biblical studies\"},{\"name\":\"Critical Thinking\",\"value\":\"Improved critical reading and analysis skills\"},{\"name\":\"Cultural Understanding\",\"value\":\"Better understanding of ancient religious cultures\"}]','2026-01-30','An overview of the Bible as an anthology. Focuses on the literary genres (epic, law, poetry, gospel) and the geographical/political setting of the Ancient Near East.','[{\"title\":\"Structure of the Bible\",\"text\":\"Understand the structure and major sections of the Bible\"},{\"title\":\"Literary Genres\",\"text\":\"Identify key literary genres such as law, poetry, and gospel\"},{\"title\":\"Historical Context\",\"text\":\"Explore the historical and cultural context of biblical texts\"}]','[{\"question\":\"Q1. Who can enroll in this course?\",\"answer\":\"This course is open to undergraduate students with an interest in religious or biblical studies.\"},{\"question\":\"What topics are covered in this course?\",\"answer\":\"The course covers biblical structure, literary genres, and historical context.\"},{\"question\":\"Do I need prior knowledge of the Bible?\",\"answer\":\"No prior knowledge is required. This course is designed for beginners.\"}]','[{\"name\":\"To be announced\",\"professional_title\":\"Senior Lecturer of Introduction to Biblical Literature\",\"photo\":\"314\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:00:17','2026-01-16 04:03:30'),
(11,3,3,6,19,NULL,NULL,'History of the Biblical Canon','How the Biblical Texts Were Selected and Preserved',NULL,NULL,'History-of-the-Biblical-Canon','333',2,'DDJI_f8bTUM',1,3.00,NULL,100.00,'[{\"name\":\"Historical Insight\",\"value\":\"Gain a deeper understanding of the origins of the biblical canon\"},{\"name\":\"Analytical Skills\",\"value\":\"Develop critical thinking through historical evaluation of texts\"},{\"name\":\"Academic Readiness\",\"value\":\"Prepare for advanced studies in theology and religious history\"}]','2026-01-30','A scientific study of the \"Selection Process.\" This course examines why certain books were excluded (Apocrypha/Gnostics) and how institutional councils finalized the list based on political and social needs.','[{\"title\":\"Canon Formation\",\"text\":\"Understand how and why biblical books were selected or excluded.\"},{\"title\":\"Apocrypha & Gnostic Texts\",\"text\":\"Study non-canonical writings and their significance\"},{\"title\":\"Councils & Authority\",\"text\":\"Understand how councils and institutions shaped the canon\"}]','[{\"question\":\"Who should take this course?\",\"answer\":\"Undergraduate students interested in biblical history and textual studies.\"},{\"question\":\"Is this course faith-based or academic?\",\"answer\":\"The course follows an academic and historical approach.\"},{\"question\":\"Will non-canonical texts be studied?\",\"answer\":\"Yes, the Apocrypha and Gnostic writings are key topics.\"}]','[{\"name\":\"To be announced\",\"professional_title\":\"Senior Lecturer of History of the Biblical Canon\",\"photo\":\"320\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:20:04','2026-01-16 04:04:59'),
(12,3,2,6,19,1,1,'The Documentary Hypothesis (Pentateuchal Studies)','A non-faith-based analysis of the first five books','Biblical Studies','BIBL150','The-Documentary-Hypothesis-Pentateuchal-Studies','335',2,'KFp8n5tqsRU',1,3.00,NULL,100.00,'[{\"name\":\"Critical Analysis\",\"value\":\"Understand the historical compilation of the Pentateuch\"}, {\"name\":\"Textual Comparison\",\"value\":\"Compare different manuscript traditions\"}]','2026-02-01','A non-faith-based analysis of the first five books. Investigates the theory that four distinct scribal groups (J, E, D, P) compiled these texts over centuries.','[{\"title\":\"Pentateuchal Sources\",\"text\":\"Learn to identify J, E, D, P source material in the text\"}, {\"title\":\"Historical Context\",\"text\":\"Study the socio-political reasons behind textual compilation\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate students in Religious Studies and Biblical Studies\"}]','[{\"name\":\"To be announced\",\"professional_title\":\"Professor of Biblical Studies\",\"photo\":\"322\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 02:49:26'),
(13,3,5,6,19,1,1,'Philology of Ancient Texts','An introduction to the evolution of Hebrew, Aramaic, and Koine Greek. Studies how translation \"shifts\" the meaning of original logical concepts.','Philology','LING180','Philology-of-Ancient-Texts','331',2,'y2MyGinS3G8',1,3.00,NULL,100.00,'[{\"name\":\"Language Analysis\",\"value\":\"Understand the evolution of Biblical languages\"}, {\"name\":\"Translation Awareness\",\"value\":\"Study how translations shift meaning\"}]','2026-02-01','An introduction to the evolution of Hebrew, Aramaic, and Koine Greek. Studies how translation \"shifts\" the meaning of original logical concepts.','[{\"title\":\"Language Evolution\",\"text\":\"Explore the historical development of Biblical languages\"}, {\"title\":\"Translation Studies\",\"text\":\"Analyze textual meaning shifts in translation\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate students interested in Biblical languages and philology\"}]','[{\"name\":\"To be announced\",\"professional_title\":\"Professor of Ancient Texts\",\"photo\":\"323\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 02:46:54'),
(14,3,46,6,19,1,1,'Hermeneutics & Formal Logic','Teaches the \"Logic of Interpretation.\" Students learn to build syllogisms based on textual evidence rather than theological assumptions.','Logic','LOGIC201','Hermeneutics-Formal-Logic','336',2,'HdfrVBynNew',1,3.00,NULL,100.00,'[{\"name\":\"Analytical Thinking\",\"value\":\"Develop logical reasoning based on textual evidence\"}, {\"name\":\"Interpretation Skills\",\"value\":\"Learn to construct syllogisms from scriptural texts\"}]','2026-01-01','Teaches the \"Logic of Interpretation.\" Students learn to build syllogisms based on textual evidence rather than theological assumptions.','[{\"title\":\"Logic Foundations\",\"text\":\"Understand the basics of formal logic and argument construction\"}, {\"title\":\"Hermeneutical Application\",\"text\":\"Apply logic to interpret Biblical texts critically\"}]','[{\"question\":\"Who should take this course?\",\"answer\":\"Undergraduate students studying Biblical studies or philosophy\"}]','[{\"name\":\"Dr. Michael Levin\",\"professional_title\":\"Professor of Logic and Hermeneutics\",\"photo\":\"324\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 03:18:36'),
(15,3,4,6,19,1,1,'Biblical Archaeology & Material Culture','Study the archaeology and artifacts of the Biblical world','ARCH','ARCH120','Biblical-Archaeology-Material-Culture','334',2,'KnTBQ17KMR8',45,3.00,NULL,100.00,'[{\"name\":\"Hands-On Experience\",\"value\":\"Learn to analyze artifacts and stratigraphy in context\"},{\"name\":\"Historical Insights\",\"value\":\"Compare archaeological findings with Biblical narratives\"}]','2026-02-01','Uses carbon dating, stratigraphy, and artifact analysis to compare the biblical narrative with the physical record of the Levant from 1200 BCE to 100 CE.','[{\"title\":\"Archaeological Skills\",\"text\":\"Gain practical knowledge in artifact interpretation\"},{\"title\":\"Historical Context\",\"text\":\"Understand the cultural and historical significance of findings\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate students in Religious Studies\"}]','[{\"name\":\"Dr. Jane Doe\",\"professional_title\":\"Professor of Biblical Archaeology\",\"photo\":\"321\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 02:48:51'),
(16,3,7,6,19,1,1,'Ancient Cosmology vs. Modern Physics','A comparative study of the Genesis \"Three-Tiered Universe\" vs. Big Bang cosmology and Quantum Theory','SCI','SCI210','Ancient-Cosmology-vs-Modern-Physics','337',2,'H0m97YJavH4',1,3.00,NULL,100.00,'[{\"name\":\"Critical Thinking\",\"value\":\"Explore ancient cosmological models in light of modern physics\"},{\"name\":\"Scientific Literacy\",\"value\":\"Compare religious texts with contemporary scientific theories\"}]','2026-02-01','A comparative study of the Genesis \"Three-Tiered Universe\" (Heavens, Earth, Abyss) vs. Big Bang cosmology and Quantum Theory.','[{\"title\":\"Interdisciplinary Understanding\",\"text\":\"Analyze the intersection of theology and physics\"},{\"title\":\"Conceptual Clarity\",\"text\":\"Understand cosmological frameworks from multiple perspectives\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students interested in the intersection of religion and science\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 03:22:11'),
(17,3,8,6,19,1,1,'Sociology of Early Israelite Religion','Analyzes the transition from tribal henotheism to national monotheism as a survival strategy','SOC','SOC230','Sociology-of-Early-Israelite-Religion','342',2,'gVlEtKwBEb8',1,3.00,NULL,100.00,'[{\"name\":\"Historical Insight\",\"value\":\"Understand the social evolution of religious beliefs in early Israel\"},{\"name\":\"Analytical Skills\",\"value\":\"Examine how societal pressures shaped religious transformations\"}]','2026-02-01','Analyzes the transition from tribal henotheism (worship of one god among many) to national monotheism as a survival strategy.','[{\"title\":\"Societal Understanding\",\"text\":\"Explore the social structures influencing religious evolution\"},{\"title\":\"Comparative Analysis\",\"text\":\"Compare early Israelite religion with other contemporary belief systems\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate students in Religious Studies or Sociology\"},{\"question\":\"Are prerequisites required?\",\"answer\":\"No prerequisites are needed\"},{\"question\":\"What will I gain?\",\"answer\":\"A deep understanding of religious and social dynamics in early Israel\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"326\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 03:54:50'),
(18,3,2,6,19,1,1,'The Synoptic Problem','A logical \"detective\" course using source criticism to map how Matthew and Luke copied from Mark and the hypothetical \"Q\" document','BIBL','BIBL260','The-Synoptic-Problem','344',2,'2TnUoxWHPF8',1,3.00,NULL,100.00,'[{\"name\":\"Analytical Skills\",\"value\":\"Develop critical thinking by tracing sources of the Synoptic Gospels\"},{\"name\":\"Historical Insight\",\"value\":\"Understand the relationships and influences among the Gospels\"}]','2026-02-01','A logical \"detective\" course using source criticism to map how the Gospels of Matthew and Luke copied from Mark and the hypothetical \"Q\" document.','[{\"title\":\"Source Analysis\",\"text\":\"Learn techniques to identify and compare gospel sources\"},{\"title\":\"Critical Interpretation\",\"text\":\"Gain insight into the composition and structure of the Synoptic Gospels\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students interested in Biblical studies and gospel criticism\"},{\"question\":\"Are prerequisites required?\",\"answer\":\"No prerequisites, but familiarity with the Gospels is helpful\"},{\"question\":\"What skills will I gain?\",\"answer\":\"Source analysis, critical reasoning, and historical interpretation skills\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"325\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 04:07:35'),
(19,3,9,6,19,1,1,'Epistemology & Biblical Truth Claims','Examines how we know what we know about the Bible. Analyzes the difference between historical fact, literary truth, and religious dogma.','PHIL','PHIL280','Epistemology-Biblical-Truth-Claims','343',2,'E2rL9x6xEHE',1,3.00,NULL,100.00,'[{\"name\":\"Critical Thinking\",\"value\":\"Develop skills to distinguish historical, literary, and religious claims\"},{\"name\":\"Analytical Skills\",\"value\":\"Evaluate evidence and arguments about biblical truth\"}]','2026-02-01','Examines how we know what we know about the Bible. Analyzes the difference between historical fact, literary truth, and religious dogma.','[{\"title\":\"Epistemological Analysis\",\"text\":\"Learn methods to assess claims about biblical knowledge\"},{\"title\":\"Literary Interpretation\",\"text\":\"Understand how texts convey meaning differently from historical fact\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Undergraduates in Religious Studies or Philosophy\"},{\"question\":\"Prerequisites?\",\"answer\":\"None, open to all students\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to critically evaluate biblical claims\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"327\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 04:06:54'),
(20,3,10,6,19,1,1,'The Historical Jesus: Methods & Criteria','Uses the \"Criteria of Embarrassment\" and \"Multiple Attestation\" to determine which deeds and sayings can be scientifically attributed to the man, Jesus of Nazareth.','CHRIS','CHRIS301','The-Historical-Jesus-Methods-Criteria','345',2,'VVzouTUE9CE',1,3.00,NULL,100.00,'[{\"name\":\"Historical Methods\",\"value\":\"Learn criteria for evaluating historical reliability of gospel accounts\"},{\"name\":\"Critical Analysis\",\"value\":\"Develop skills to differentiate historical facts from theological interpretation\"}]','2026-02-01','Uses the \"Criteria of Embarrassment\" and \"Multiple Attestation\" to determine which deeds and sayings can be scientifically attributed to the man, Jesus of Nazareth.','[{\"title\":\"Historical Reasoning\",\"text\":\"Apply scientific methods to biblical texts\"},{\"title\":\"Source Evaluation\",\"text\":\"Critically assess multiple gospel sources\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students of Biblical studies and theology\"},{\"question\":\"Prerequisites?\",\"answer\":\"None, open to all undergraduates\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to assess historical claims about Jesus\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"328\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 04:10:10'),
(21,3,11,6,19,1,1,'Developmental Christology','Traces the logical evolution of Jesus’ identity from a Jewish prophet (Mark) to the Cosmic Logos (John) to the God-Man of the 4th-century councils.','THEO','THEO320','Developmental-Christology','347',2,'U31dLca5MeY',1,3.00,NULL,100.00,'[{\"name\":\"Theological Insight\",\"value\":\"Understand the historical development of Christological thought\"},{\"name\":\"Analytical Skills\",\"value\":\"Analyze changes in doctrinal interpretation over time\"}]','2026-02-01','Traces the logical evolution of Jesus’ identity from a Jewish prophet (Mark) to the Cosmic Logos (John) to the God-Man of the 4th-century councils.','[{\"title\":\"Historical Theology\",\"text\":\"Examine development of Christology across centuries\"},{\"title\":\"Doctrinal Analysis\",\"text\":\"Understand theological debates and decisions\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students interested in Christology and theology\"},{\"question\":\"Prerequisites?\",\"answer\":\"Basic knowledge of New Testament recommended\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to trace theological evolution of Jesus’ identity\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"329\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 04:17:13'),
(22,3,3,6,19,1,1,'Second Temple Judaism & The Dead Sea Scrolls','Analyzes the Qumran library and its scientific impact on our understanding of how the Bible was preserved and changed by Jewish sects.','HIST','HIST340','Second-Temple-Judaism-The-Dead-Sea-Scrolls','352',2,'Oyi7DTwAr5A',1,3.00,NULL,100.00,'[{\"name\":\"Historical Insight\",\"value\":\"Understand Jewish sects and biblical transmission\"},{\"name\":\"Research Skills\",\"value\":\"Analyze ancient manuscripts and interpret historical context\"}]','2026-02-01','Analyzes the Qumran library and its scientific impact on our understanding of how the Bible was preserved and changed by Jewish sects.','[{\"title\":\"Manuscript Analysis\",\"text\":\"Study textual variants in the Dead Sea Scrolls\"},{\"title\":\"Contextual Understanding\",\"text\":\"Interpret historical significance of Second Temple Judaism\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students interested in Jewish history and biblical manuscripts\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to analyze and contextualize biblical texts\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 04:31:38'),
(23,3,2,6,19,1,1,'Pauline Epistles & Ancient Rhetoric','A study of Paul’s letters using Greco-Roman rhetorical logic. Analyzes his arguments on law and grace as philosophical debates rather than \"sermons.\"','BIBL','BIBL360','Pauline-Epistles-Ancient-Rhetoric','353',2,'L6vHZX2on_U',1,3.00,NULL,100.00,'[{\"name\":\"Rhetorical Skills\",\"value\":\"Learn how Paul structured arguments using Greco-Roman rhetorical techniques\"},{\"name\":\"Critical Interpretation\",\"value\":\"Analyze theological debates on law and grace\"}]','2026-02-01','A study of Paul’s letters using Greco-Roman rhetorical logic. Analyzes his arguments on law and grace as philosophical debates rather than \"sermons.\"','[{\"title\":\"Rhetorical Analysis\",\"text\":\"Examine the logic and structure of Paul’s letters\"},{\"title\":\"Philosophical Insight\",\"text\":\"Understand debates on law and grace in context\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students of Biblical studies and rhetoric\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to critically analyze Pauline texts\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 04:33:50'),
(24,3,7,6,19,1,1,'Bioethics & Biblical Law','Connects ancient purity laws and \"life\" definitions with modern medical ethics, genetic engineering, and environmental science.','SCI','SCI380','Bioethics-Biblical-Law','356',2,'8PBVzjr1D9A',1,3.00,NULL,100.00,'[{\"name\":\"Ethical Analysis\",\"value\":\"Apply biblical principles to modern bioethical dilemmas\"},{\"name\":\"Interdisciplinary Insight\",\"value\":\"Connect religious law with science and medicine\"}]','2026-02-01','Connects ancient purity laws and \"life\" definitions with modern medical ethics, genetic engineering, and environmental science.','[{\"title\":\"Ethics & Law\",\"text\":\"Analyze modern ethical challenges through biblical law\"},{\"title\":\"Scientific Context\",\"text\":\"Understand biological and environmental principles influencing ethics\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students interested in ethics, religion, and science\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to bridge biblical law with modern bioethics\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 04:56:38'),
(25,3,9,6,19,1,1,'Metaphysics of the Logos','A deep dive into the Greek concept of Logos (Reason) and how it served as a bridge between Greek science/philosophy and Early Christian theology.','PHIL','PHIL410','Metaphysics-of-the-Logos','300',2,'qKq0Afmsj-U',1,3.00,NULL,100.00,'[{\"name\":\"Philosophical Insight\",\"value\":\"Explore how Logos connects Greek thought with Christian theology\"},{\"name\":\"Analytical Skills\",\"value\":\"Understand metaphysical concepts and reasoning\"}]','2026-02-01','A deep dive into the Greek concept of Logos (Reason) and how it served as a bridge between Greek science/philosophy and Early Christian theology.','[{\"title\":\"Conceptual Analysis\",\"text\":\"Examine the Greek notion of Logos\"},{\"title\":\"Theological Bridge\",\"text\":\"Understand its role in Early Christian thought\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students of philosophy, theology, and religious studies\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to integrate philosophical and theological ideas\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 02:02:52'),
(26,3,2,6,19,1,1,'Textual Criticism (Paleography)','The \"Science of Mistakes.\" Students learn how scholars reconstruct the original text from 5,000+ conflicting manuscripts using logical probability.','BIBL','BIBL430','Textual-Criticism-Paleography','364',2,'NBkJ4hEhUW4',1,3.00,NULL,100.00,'[{\"name\":\"Analytical Skills\",\"value\":\"Learn methods to reconstruct original texts from manuscripts\"},{\"name\":\"Critical Thinking\",\"value\":\"Apply probability and logic to textual variants\"}]','2026-02-01','The \"Science of Mistakes.\" Students learn how scholars reconstruct the original text from 5,000+ conflicting manuscripts using logical probability.','[{\"title\":\"Text Reconstruction\",\"text\":\"Understand techniques for determining original readings\"},{\"title\":\"Historical Context\",\"text\":\"Analyze the evolution of manuscripts over time\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students interested in biblical manuscripts and textual criticism\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to critically analyze and reconstruct texts\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 05:54:02'),
(27,3,11,6,19,1,1,'Theodicy & The Problem of Evil','A logical analysis of how the Bible attempts to reconcile an all-powerful deity with the presence of natural disasters and suffering.','THEO','THEO450','Theodicy-The-Problem-of-Evil','367',2,'Oo4hF3IYGp4',1,3.00,NULL,100.00,'[{\"name\":\"Philosophical Insight\",\"value\":\"Understand theological approaches to evil and suffering\"},{\"name\":\"Critical Thinking\",\"value\":\"Analyze logical arguments reconciling divine power with evil\"}]','2026-02-01','A logical analysis of how the Bible attempts to reconcile an all-powerful deity with the presence of natural disasters and suffering.','[{\"title\":\"Logical Analysis\",\"text\":\"Evaluate biblical explanations for suffering\"},{\"title\":\"Philosophical Context\",\"text\":\"Understand theodicy in historical and modern perspectives\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students interested in theology, philosophy, and religious studies\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to critically evaluate the problem of evil\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 06:03:14'),
(28,3,12,6,19,1,1,'Psychology of Religious Experience','A scientific look at \"Prophecy\" and \"Revelation\" through the lens of neuroscience and cognitive psychology.','RELI','RELI470','Psychology-of-Religious-Experience','369',2,'C3CgyXDyuwk',1,3.00,NULL,100.00,'[{\"name\":\"Scientific Insight\",\"value\":\"Examine religious experiences using neuroscience and psychology\"},{\"name\":\"Analytical Skills\",\"value\":\"Understand cognitive mechanisms behind prophecy and revelation\"}]','2026-02-01','A scientific look at \"Prophecy\" and \"Revelation\" through the lens of neuroscience and cognitive psychology.','[{\"title\":\"Cognitive Analysis\",\"text\":\"Study mental processes involved in religious experiences\"},{\"title\":\"Scientific Approach\",\"text\":\"Apply neuroscience concepts to understand prophecy and revelation\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students interested in psychology, neuroscience, and religious studies\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to analyze religious experiences scientifically\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 06:10:19'),
(29,3,13,6,19,1,1,'Senior Research Capstone','An independent research project where students must apply a scientific or logical methodology to a specific biblical problem (e.g., \"A Linguistic Analysis of the Book of Job\").','CAP','CAP499','Senior-Research-Capstone','376',2,'_MbD1PocH6U',1,3.00,NULL,100.00,'[{\"name\":\"Research Skills\",\"value\":\"Develop independent research methodology\"},{\"name\":\"Critical Analysis\",\"value\":\"Apply scientific and logical analysis to biblical studies\"}]','2026-02-01','An independent research project where students must apply a scientific or logical methodology to a specific biblical problem (e.g., \"A Linguistic Analysis of the Book of Job\").','[{\"title\":\"Independent Research\",\"text\":\"Plan and execute a scholarly research project\"},{\"title\":\"Analytical Thinking\",\"text\":\"Critically evaluate primary and secondary sources\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Senior undergraduates completing their degree\"},{\"question\":\"Prerequisites?\",\"answer\":\"Completion of core biblical studies courses\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to conduct and present original research\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 06:34:08'),
(30,3,2,6,19,1,1,'From Elohim to Yahweh: Source Criticism & Divine Identity','A study of the shifting concept of God from the universal creator (Elohim, P/E sources) to the covenant God of Israel (Yahweh, J source). Examines historical sources for Creation and Flood narratives in the Ancient Near East (e.g., Enuma Elish, Gilgamesh).','BIBL','BIBL111','From-Elohim-to-Yahweh-Source-Criticism-Divine-Identity','378',2,'U5iyUik97Lg',1,3.00,NULL,100.00,'[{\"name\":\"Textual Insight\",\"value\":\"Learn to apply source criticism to biblical texts\"},{\"name\":\"Historical Understanding\",\"value\":\"Explore ancient Near Eastern influences on Israelite religion\"}]','2026-02-01','A study of the shifting concept of God from the universal creator (Elohim, P/E sources) to the covenant God of Israel (Yahweh, J source). Examines historical sources for Creation and Flood narratives in the Ancient Near East (e.g., Enuma Elish, Gilgamesh).','[{\"title\":\"Source Criticism\",\"text\":\"Analyze textual sources and their historical contexts\"},{\"title\":\"Divine Identity\",\"text\":\"Trace the evolution of Israelite conception of God\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Undergraduate students in biblical studies\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to critically evaluate biblical source material\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 06:42:14'),
(31,3,2,6,19,1,1,'Yahweh as Liberator: Historical Roots of Monotheism','Analyzes the development of a national deity, Yahweh, focusing on the historical and sociological context of the Exodus event. Investigates archaeological evidence for the settlement and the influence of Egyptian polytheism on early Israelite theology.','BIBL','BIBL121','Yahweh-as-Liberator-Historical-Roots-of-Monotheism','379',2,'mdKst8zeh-U',1,3.00,NULL,100.00,'[{\"name\":\"Historical Context\",\"value\":\"Understand the sociological and historical background of monotheism\"},{\"name\":\"Analytical Skills\",\"value\":\"Evaluate archaeological and textual evidence\"}]','2026-02-01','Analyzes the development of a national deity, Yahweh, focusing on the historical and sociological context of the Exodus event. Investigates archaeological evidence for the settlement and the influence of Egyptian polytheism on early Israelite theology.','[{\"title\":\"Historical Analysis\",\"text\":\"Examine evidence for the Exodus and early Israelite religion\"},{\"title\":\"Sociological Insight\",\"text\":\"Understand how societal context shaped theology\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students interested in biblical history and archaeology\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to analyze the historical roots of monotheism\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 06:43:47'),
(32,3,2,6,19,1,1,'Holiness and Purity: Anthropology of the Priestly God','Examines the Priestly (P) source\'s concept of an absolutely holy God. Focuses on the historical evolution of purity laws, sacrifice, and the function of the Tabernacle as a method for controlling divine presence within a pre-scientific worldview.','BIBL','BIBL131','Holiness-and-Purity-Anthropology-of-the-Priestly-God','384',2,'URMs-17otFE',1,3.00,NULL,100.00,'[{\"name\":\"Theological Insight\",\"value\":\"Explore the concept of holiness in Priestly texts\"},{\"name\":\"Anthropological Understanding\",\"value\":\"Examine purity laws and ritual practices\"}]','2026-02-01','Examines the Priestly (P) source\'s concept of an absolutely holy God. Focuses on the historical evolution of purity laws, sacrifice, and the function of the Tabernacle as a method for controlling divine presence within a pre-scientific worldview.','[{\"title\":\"Ritual Analysis\",\"text\":\"Understand sacrificial and purity practices\"},{\"title\":\"Textual Insight\",\"text\":\"Analyze the P source within historical context\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students of biblical studies and anthropology\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to analyze theological and anthropological concepts in biblical texts\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 07:03:41'),
(33,3,2,6,19,1,1,'God in the Wilderness: Trials, Covenant, and Rebellion','Studies the theological function of the 40-year wilderness narrative. Examines the historical challenges of tribal consolidation and the literary sources (J, E, P) that shaped the concept of a disciplined and testing deity.','BIBL','BIBL141','God-in-the-Wilderness-Trials-Covenant-and-Rebellion','385',2,'VJQuOUwEesI',1,3.00,NULL,100.00,'[{\"name\":\"Narrative Analysis\",\"value\":\"Understand theological and literary aspects of wilderness narratives\"},{\"name\":\"Historical Insight\",\"value\":\"Examine the challenges faced by Israelite tribes\"}]','2026-02-01','Studies the theological function of the 40-year wilderness narrative. Examines the historical challenges of tribal consolidation and the literary sources (J, E, P) that shaped the concept of a disciplined and testing deity.','[{\"title\":\"Literary Analysis\",\"text\":\"Analyze sources and themes of the wilderness narrative\"},{\"title\":\"Historical Context\",\"text\":\"Understand the societal challenges influencing the narrative\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students of biblical studies and theology\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to analyze biblical narratives in historical and theological context\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 07:05:28'),
(34,3,2,6,19,1,1,'The Deuteronomistic God: Centralization of Worship and Justice','Focuses on the unique concept of God championed by the Deuteronomistic Historians (D source)—a God whose singular demand is exclusive loyalty to a central sanctuary. Analyzes the historical context of Josiah’s reforms (7th century BCE).','BIBL','BIBL151','The-Deuteronomistic-God-Centralization-of-Worship-and-Justice','388',2,'R0wHaEYItas',1,3.00,NULL,100.00,'[{\"name\":\"Theological Insight\",\"value\":\"Understand the Deuteronomistic concept of God\"},{\"name\":\"Historical Context\",\"value\":\"Analyze Josiah\'s religious reforms and centralization\"}]','2026-02-01','Focuses on the unique concept of God championed by the Deuteronomistic Historians (D source)—a God whose singular demand is exclusive loyalty to a central sanctuary. Analyzes the historical context of Josiah’s reforms (7th century BCE).','[{\"title\":\"Textual Analysis\",\"text\":\"Examine the D source texts\"},{\"title\":\"Historical Insight\",\"text\":\"Understand the reforms of 7th century BCE Judah\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Undergraduate biblical studies students\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to analyze Deuteronomistic texts and historical context\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 07:14:47'),
(35,3,2,6,19,1,1,'The God of Holy War: Ethics and Archaeology of Conquest','A critical investigation into the concept of herem (devotion to destruction) and the \"warrior God.\" Compares the biblical conquest narrative with archaeological evidence for the historical settlement of the Levant.','BIBL','BIBL201','The-God-of-Holy-War-Ethics-and-Archaeology-of-Conquest','392',2,'OiJQBrHkqso',1,3.00,NULL,100.00,'[{\"name\":\"Ethical Analysis\",\"value\":\"Explore moral dimensions of biblical holy war\"},{\"name\":\"Archaeological Insight\",\"value\":\"Compare biblical narratives with material evidence\"}]','2026-02-01','A critical investigation into the concept of herem (devotion to destruction) and the \"warrior God.\" Compares the biblical conquest narrative with archaeological evidence for the historical settlement of the Levant.','[{\"title\":\"Ethical Evaluation\",\"text\":\"Understand the moral questions raised by holy war\"},{\"title\":\"Historical Analysis\",\"text\":\"Compare biblical texts with archaeological data\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students interested in biblical ethics and archaeology\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to critically assess holy war narratives in the Bible\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 07:35:38'),
(36,3,2,6,19,1,1,'Decentralized Divinity: The Cyclic God of Chaos and Rescue','Analyzes the cyclical narrative of sin, punishment, and deliverance, reflecting a period of political fragmentation. Explores the sociological context of tribal henotheism and the rise of charismatic, local leadership (Judges).','BIBL','BIBL211','Decentralized-Divinity-The-Cyclic-God-of-Chaos-and-Rescue','394',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Sociological Insight\",\"value\":\"Examine how political fragmentation influenced religious narratives\"},{\"name\":\"Literary Analysis\",\"value\":\"Understand cyclical storytelling in Judges\"}]','2026-02-01','Analyzes the cyclical narrative of sin, punishment, and deliverance, reflecting a period of political fragmentation. Explores the sociological context of tribal henotheism and the rise of charismatic, local leadership (Judges).','[{\"title\":\"Narrative Analysis\",\"text\":\"Identify patterns of sin and deliverance\"},{\"title\":\"Social Context\",\"text\":\"Understand historical tribal dynamics\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students of biblical history and literature\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to analyze cyclical patterns and social context in biblical narratives\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 07:39:34'),
(37,3,2,6,19,1,1,'The God of Providence: Loyalty and Social Inclusion in Moab','Focuses on the concept of a compassionate, intervening God working through seemingly secular human affairs. Examines the historical role of women and the legal and social sources governing the inclusion of non-Israelites (Moabites) into the community.','BIBL','BIBL221','The-God-of-Providence-Loyalty-and-Social-Inclusion-in-Moab','300',2,'j0E_a_rNqD0',1,3.00,NULL,100.00,'[{\"name\":\"Social Insight\",\"value\":\"Understand social and legal inclusion in biblical times\"},{\"name\":\"Theological Insight\",\"value\":\"Analyze the role of divine providence in human affairs\"}]','2026-02-01','Focuses on the concept of a compassionate, intervening God working through seemingly secular human affairs. Examines the historical role of women and the legal and social sources governing the inclusion of non-Israelites (Moabites) into the community.','[{\"title\":\"Social Analysis\",\"text\":\"Examine inclusion of Moabites and roles of women\"},{\"title\":\"Theological Reflection\",\"text\":\"Understand divine intervention in human events\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students of biblical theology and social history\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to analyze biblical social and theological dynamics\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 03:07:48'),
(38,3,2,6,19,1,1,'God and the Monarchy: The Shift from Prophets to Kings','Studies the political theology of the transition from a theocratic tribal league to a centralized monarchy under Saul and David. Examines the source tension between those who favored (pro-monarchy) and opposed (pro-prophet) the kingship.','BIBL','BIBL231','god-and-the-monarchy-the-shift-from-prophets-to-kings','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Political Insight\",\"value\":\"Analyze the shift from tribal to monarchical governance\"},{\"name\":\"Theological Analysis\",\"value\":\"Understand prophetic vs. royal perspectives\"}]','2026-02-01','Studies the political theology of the transition from a theocratic tribal league to a centralized monarchy under Saul and David. Examines the source tension between those who favored (pro-monarchy) and opposed (pro-prophet) the kingship.','[{\"title\":\"Historical Analysis\",\"text\":\"Examine the political and theological transition\"},{\"title\":\"Source Criticism\",\"text\":\"Analyze pro-monarchy vs. pro-prophet sources\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students of biblical history and political theology\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to evaluate political-theological narratives in the Bible\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(39,3,2,6,19,1,1,'David\'s God: The Messianic Line and Dynasty Theology','A critical look at the formulation of the permanent covenant with David (2 Samuel 7) and the theological creation of the \"Messiah\" concept. Analyzes historical evidence for David\'s rule and its political consolidation.','BIBL','BIBL241','davids-god-the-messianic-line-and-dynasty-theology','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Messianic Insight\",\"value\":\"Understand the theological creation of the Messiah concept\"},{\"name\":\"Historical Analysis\",\"value\":\"Study David\'s rule and political consolidation\"}]','2026-02-01','A critical look at the formulation of the permanent covenant with David (2 Samuel 7) and the theological creation of the \"Messiah\" concept. Analyzes historical evidence for David\'s rule and its political consolidation.','[{\"title\":\"Textual Analysis\",\"text\":\"Examine 2 Samuel 7 and related texts\"},{\"title\":\"Historical Context\",\"text\":\"Understand the political consolidation of David\'s kingdom\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Undergraduate students in biblical studies\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to analyze the Davidic covenant and Messianic concepts\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(40,3,2,6,19,1,1,'The Divided God: Temple, Wisdom, and Schism','Examines the concept of God tied to the Jerusalem Temple (Solomon). Analyzes the historical sources documenting the division of the kingdom (Israel and Judah) and the theological justifications for the schism and the northern kingdom\'s alternative forms of worship.','BIBL','BIBL301','the-divided-god-temple-wisdom-and-schism','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Theological Insight\",\"value\":\"Explore God\'s association with the Temple and wisdom traditions\"},{\"name\":\"Historical Context\",\"value\":\"Analyze the division of Israel and Judah\"}]','2026-02-01','Examines the concept of God tied to the Jerusalem Temple (Solomon). Analyzes the historical sources documenting the division of the kingdom (Israel and Judah) and the theological justifications for the schism and the northern kingdom\'s alternative forms of worship.','[{\"title\":\"Textual Analysis\",\"text\":\"Examine sources on Temple and wisdom traditions\"},{\"title\":\"Historical Analysis\",\"text\":\"Understand the political and religious schism\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Undergraduate students in biblical studies\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Analyze theological and historical schisms in Israelite history\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(41,1,1,6,19,1,1,'The God of Judgment and Exile: Prophetic Critique of History','Studies the Deuteronomistic framework that interprets the fall of both Israel (722 BCE) and Judah (586 BCE) as divine judgment for covenant violation. Analyzes the historical reliability of the prophetic narratives and their influence on the concept of God.','BIBL','BIBL311','the-god-of-judgment-and-exile-prophetic-critique-of-history','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Prophetic Insight\",\"value\":\"Understand the Deuteronomistic interpretation of Israel\'s fall\"},{\"name\":\"Historical Analysis\",\"value\":\"Examine the reliability of prophetic narratives\"}]','2026-02-01','Studies the Deuteronomistic framework that interprets the fall of both Israel (722 BCE) and Judah (586 BCE) as divine judgment for covenant violation. Analyzes the historical reliability of the prophetic narratives and their influence on the concept of God.','[{\"title\":\"Textual Critique\",\"text\":\"Evaluate prophetic accounts\"},{\"title\":\"Historical Context\",\"text\":\"Analyze the fall of Israel and Judah\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students of biblical history and prophecy\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to critically assess prophetic critiques of history\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(42,3,2,6,19,1,1,'The God of Judgment and Exile: Prophetic Critique of History','Studies the Deuteronomistic framework that interprets the fall of both Israel (722 BCE) and Judah (586 BCE) as divine judgment for covenant violation. Analyzes the historical reliability of the prophetic narratives and their influence on the concept of God.','BIBL','BIBL311','the-god-of-judgment-and-exile-prophetic-critique-of-history','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Prophetic Insight\",\"value\":\"Understand the Deuteronomistic interpretation of Israel\'s fall\"},{\"name\":\"Historical Analysis\",\"value\":\"Examine the reliability of prophetic narratives\"}]','2026-02-01','Studies the Deuteronomistic framework that interprets the fall of both Israel (722 BCE) and Judah (586 BCE) as divine judgment for covenant violation. Analyzes the historical reliability of the prophetic narratives and their influence on the concept of God.','[{\"title\":\"Textual Critique\",\"text\":\"Evaluate prophetic accounts\"},{\"title\":\"Historical Context\",\"text\":\"Analyze the fall of Israel and Judah\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students of biblical history and prophecy\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to critically assess prophetic critiques of history\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(43,3,2,6,19,1,1,'The God of Cultic Restoration: Post-Exilic Re-Imagining','Focuses on the Chronicler\'s attempt (Post-Exile) to re-center the concept of God entirely around the Temple and the Levites, minimizing the failures of the early kings. Analyzes this as a theological and historical revisionism.','BIBL','BIBL321','the-god-of-cultic-restoration-post-exilic-re-imagining','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Restoration Insight\",\"value\":\"Understand the Chronicler\'s post-exilic theological focus\"},{\"name\":\"Historical Revision\",\"value\":\"Analyze changes in interpretation of early kings\"}]','2026-02-01','Focuses on the Chronicler\'s attempt (Post-Exile) to re-center the concept of God entirely around the Temple and the Levites, minimizing the failures of the early kings. Analyzes this as a theological and historical revisionism.','[{\"title\":\"Theological Analysis\",\"text\":\"Examine post-exilic interpretations\"},{\"title\":\"Historical Context\",\"text\":\"Understand Chronicler\'s modifications\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students of biblical theology and history\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to analyze post-exilic theological and historical narratives\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(44,3,2,6,19,1,1,'The God of Hope: Rewriting History for the Future','Continues the Chronicler\'s work, emphasizing the divine desire for repentance and restoration. Explores the historical context of the return from Babylonian exile and the theological need to demonstrate God\'s enduring commitment to the Davidic line.','BIBL','BIBL331','the-god-of-hope-rewriting-history-for-the-future','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Hopeful Theology\",\"value\":\"Explore the theme of divine commitment and restoration\"},{\"name\":\"Historical Insight\",\"value\":\"Study the post-exilic context of the Davidic line\"}]','2026-02-01','Continues the Chronicler\'s work, emphasizing the divine desire for repentance and restoration. Explores the historical context of the return from Babylonian exile and the theological need to demonstrate God\'s enduring commitment to the Davidic line.','[{\"title\":\"Theological Reflection\",\"text\":\"Understand themes of hope and restoration\"},{\"title\":\"Historical Context\",\"text\":\"Analyze return from Babylonian exile\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students of biblical history and theology\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to analyze hope and restoration in post-exilic texts\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(45,3,2,6,19,1,1,'The God of the Second Temple: Law, Identity, and Exclusion','Studies the post-exilic concept of a covenant God whose people are defined by strict adherence to the Law and separation from foreign influence (the Priestly focus). Analyzes the historical edicts of the Persian Empire allowing the return and rebuilding.','BIBL','BIBL401','the-god-of-the-second-temple-law-identity-and-exclusion','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Legal Insight\",\"value\":\"Understand post-exilic Law and identity formation\"},{\"name\":\"Historical Analysis\",\"value\":\"Examine Persian edicts and rebuilding efforts\"}]','2026-02-01','Studies the post-exilic concept of a covenant God whose people are defined by strict adherence to the Law and separation from foreign influence (the Priestly focus). Analyzes the historical edicts of the Persian Empire allowing the return and rebuilding.','[{\"title\":\"Theological Analysis\",\"text\":\"Study covenant and legal adherence\"},{\"title\":\"Historical Context\",\"text\":\"Analyze Persian policies and rebuilding\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students of biblical law and post-exilic history\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to analyze Second Temple identity and law\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(46,3,2,6,19,1,1,'The God of Governance: Political Action and Religious Revival','Focuses on the intersection of faith and political leadership in the restoration of Jerusalem\'s walls. Examines Nehemiah’s reliance on prayer alongside political pragmatism, reflecting a concept of God as both spiritual guide and historical agent.','BIBL','BIBL411','the-god-of-governance-political-action-and-religious-revival','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Leadership Insight\",\"value\":\"Understand the role of faith in political restoration\"},{\"name\":\"Historical Analysis\",\"value\":\"Study Nehemiah\'s combination of prayer and pragmatism\"}]','2026-02-01','Focuses on the intersection of faith and political leadership in the restoration of Jerusalem\'s walls. Examines Nehemiah’s reliance on prayer alongside political pragmatism, reflecting a concept of God as both spiritual guide and historical agent.','[{\"title\":\"Textual Analysis\",\"text\":\"Examine Nehemiah\'s narrative and strategies\"},{\"title\":\"Theological Insight\",\"text\":\"Understand God\'s role as spiritual and historical agent\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Undergraduate students in Religious Studies\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to analyze faith and leadership in historical context\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(47,3,2,6,19,1,1,'The Hidden God: Divine Silence in a Secular Narrative','A unique analysis of a book where the name of God is never mentioned. Students investigate the historical context of the Diaspora and the theological rationale for depicting God\'s presence as an unseen providential force in human history.','BIBL','BIBL421','the-hidden-god-divine-silence-in-a-secular-narrative','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Divine Insight\",\"value\":\"Understand God\'s presence in absence\"},{\"name\":\"Historical Context\",\"value\":\"Study Diaspora and unseen providence\"}]','2026-02-01','A unique analysis of a book where the name of God is never mentioned. Students investigate the historical context of the Diaspora and the theological rationale for depicting God\'s presence as an unseen providential force in human history.','[{\"title\":\"Textual Analysis\",\"text\":\"Study literary strategies for divine absence\"},{\"title\":\"Historical Insight\",\"text\":\"Analyze the Diaspora context\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Undergraduate students in Religious Studies\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to analyze theological narratives of divine silence\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(48,3,9,6,19,1,1,'Theodicy and the Concept of God\'s Power vs. Justice','A philosophical and logical analysis of the problem of evil (Theodicy). Explores the concept of a sovereign, incomprehensible God and critiques the traditional Deuteronomistic theological source that links suffering directly to sin.','PHIL','PHIL431','theodicy-and-the-concept-of-gods-power-vs-justice','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Philosophical Insight\",\"value\":\"Explore theodicy and divine justice\"},{\"name\":\"Critical Thinking\",\"value\":\"Analyze the Deuteronomistic link between suffering and sin\"}]','2026-02-01','A philosophical and logical analysis of the problem of evil (Theodicy). Explores the concept of a sovereign, incomprehensible God and critiques the traditional Deuteronomistic theological source that links suffering directly to sin.','[{\"title\":\"Philosophical Analysis\",\"text\":\"Examine the problem of evil\"},{\"title\":\"Theological Critique\",\"text\":\"Critique Deuteronomistic assumptions\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students interested in philosophy and theology\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to analyze theodicy and divine justice critically\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(49,3,12,6,19,1,1,'The Contradictory God: Emotional Experience and Worship','Studies the diverse concepts of God expressed in liturgical poetry, ranging from vengeful warrior to compassionate shepherd. Examines the historical function of the Psalms in Temple worship and their source as a reflection of lived religious experience.','RELI','RELI441','the-contradictory-god-emotional-experience-and-worship','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Emotional Insight\",\"value\":\"Understand the diverse expressions of God in liturgy\"},{\"name\":\"Historical Analysis\",\"value\":\"Study Psalms and their role in worship\"}]','2026-02-01','Studies the diverse concepts of God expressed in liturgical poetry, ranging from vengeful warrior to compassionate shepherd. Examines the historical function of the Psalms in Temple worship and their source as a reflection of lived religious experience.','[{\"title\":\"Textual Analysis\",\"text\":\"Examine Psalms for theological and emotional themes\"},{\"title\":\"Historical Insight\",\"text\":\"Understand Temple worship context\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students in Religious Studies and liturgy\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to interpret theological poetry and emotional worship\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(50,3,12,6,19,1,1,'God and Cosmic Order: Wisdom and Ethical Monotheism','Focuses on the concept of God as the source of an ordered, predictable universe (Cosmic Wisdom). Analyzes the historical relationship between Israelite wisdom literature and similar secular/international wisdom texts from Egypt and Mesopotamia.','RELI','RELI451','god-and-cosmic-order-wisdom-and-ethical-monotheism','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Wisdom Insight\",\"value\":\"Understand God\'s role in ordering the cosmos\"},{\"name\":\"Comparative Analysis\",\"value\":\"Compare Israelite and international wisdom texts\"}]','2026-02-01','Focuses on the concept of God as the source of an ordered, predictable universe (Cosmic Wisdom). Analyzes the historical relationship between Israelite wisdom literature and similar secular/international wisdom texts from Egypt and Mesopotamia.','[{\"title\":\"Wisdom Analysis\",\"text\":\"Examine ethical monotheism in biblical texts\"},{\"title\":\"Historical Comparison\",\"text\":\"Analyze cross-cultural wisdom literature\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Undergraduate students in Religious Studies\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to analyze ethical monotheism and cosmic order\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(51,3,48,6,19,1,1,'The Secret God: Jesus as the Suffering Son of God','An analysis of Markan priority and the concept of the Messianic Secret. Focuses on the swift, action-oriented concept of Jesus as the obedient, suffering servant of God, and the historical context of persecution (perhaps Roman, pre-70 CE).','NT','NT111','the-secret-god-jesus-as-the-suffering-son-of-god','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Messianic Insight\",\"value\":\"Explore Jesus\'s identity as the suffering Son of God\"},{\"name\":\"Historical Context\",\"value\":\"Understand Roman-era persecution\"}]','2026-02-01','An analysis of Markan priority and the concept of the Messianic Secret. Focuses on the swift, action-oriented concept of Jesus as the obedient, suffering servant of God, and the historical context of persecution (perhaps Roman, pre-70 CE).','[{\"title\":\"Textual Analysis\",\"text\":\"Study Markan priority and Messianic Secret\"},{\"title\":\"Historical Insight\",\"text\":\"Examine persecution context\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students in New Testament studies\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to analyze Messianic Secret in historical context\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(52,3,48,6,19,1,1,'The Universal God: Jesus and the Inclusion of the Marginalized','Examines Luke’s concept of God’s redemptive plan being realized through the inclusion of the poor, women, and Gentiles. Analyzes the historical context of the Greco-Roman world and the literary source of Luke-Acts as a unified historical apology.','NT','NT121','the-universal-god-jesus-and-the-inclusion-of-the-marginalized','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Inclusivity Insight\",\"value\":\"Understand God\'s plan through inclusion\"},{\"name\":\"Historical Context\",\"value\":\"Study Luke-Acts in Greco-Roman society\"}]','2026-02-01','Examines Luke’s concept of God’s redemptive plan being realized through the inclusion of the poor, women, and Gentiles. Analyzes the historical context of the Greco-Roman world and the literary source of Luke-Acts as a unified historical apology.','[{\"title\":\"Textual Analysis\",\"text\":\"Study Luke-Acts\' presentation of inclusivity\"},{\"title\":\"Historical Insight\",\"text\":\"Analyze Greco-Roman context\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students in New Testament studies\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to analyze inclusion theology in Luke-Acts\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(53,3,48,6,19,1,1,'The Incarnate God: Logos, Dualism, and High Christology','A philosophical-theological study of the concept of Jesus as the pre-existent Logos (Reason) who became flesh. Analyzes the book’s dualistic worldview (light/dark, above/below) and its unique source tradition, distinct from the Synoptic Gospels.','NT','NT131','the-incarnate-god-logos-dualism-and-high-christology','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Christology Insight\",\"value\":\"Explore Logos and pre-existence of Christ\"},{\"name\":\"Dualism Analysis\",\"value\":\"Understand philosophical-theological dualism\"}]','2026-02-01','A philosophical-theological study of the concept of Jesus as the pre-existent Logos (Reason) who became flesh. Analyzes the book’s dualistic worldview (light/dark, above/below) and its unique source tradition, distinct from the Synoptic Gospels.','[{\"title\":\"Textual Analysis\",\"text\":\"Study Logos and dualism concepts\"},{\"title\":\"Theological Insight\",\"text\":\"Analyze high Christology\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students in New Testament studies\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to analyze high Christology and dualism\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(54,3,48,6,19,1,1,'The God of the Spirit: Pentecost, Expansion, and the Early Church','Focuses on the concept of God acting through the Holy Spirit as a dynamic, historical agent guiding the mission from Jerusalem to Rome. Examines the sociological source of the earliest Christian communities and the historical context of Roman expansion.','NT','NT141','the-god-of-the-spirit-pentecost-expansion-and-the-early-church','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Holy Spirit Insight\",\"value\":\"Understand God\'s action through the Spirit\"},{\"name\":\"Historical Analysis\",\"value\":\"Study early church expansion and mission\"}]','2026-02-01','Focuses on the concept of God acting through the Holy Spirit as a dynamic, historical agent guiding the mission from Jerusalem to Rome. Examines the sociological source of the earliest Christian communities and the historical context of Roman expansion.','[{\"title\":\"Textual Analysis\",\"text\":\"Examine Spirit-led mission narratives\"},{\"title\":\"Historical Insight\",\"text\":\"Study early church expansion context\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Students in New Testament studies\"},{\"question\":\"Prerequisites?\",\"answer\":\"None required\"},{\"question\":\"Outcome?\",\"answer\":\"Ability to analyze Holy Spirit activity in early church\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(55,3,48,6,19,1,1,'The Just God: Righteousness, Law, and the New Humanity','A logical and theological analysis of Paul\'s primary argument for the universality of sin and God\'s justification (dikaiosynē) through faith.','New Testament','NT201','the-just-god-righteousness-law-and-the-new-humanity','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Theological Insight\",\"value\":\"Understand justification and righteousness\"},{\"name\":\"Historical Context\",\"value\":\"Analyze the Roman church setting\"}]','2026-02-01','A logical and theological analysis of Paul\'s primary argument for the universality of sin and God\'s justification (dikaiosynē) through faith. Examines the historical context of the church in Rome and the polemical source of Paul\'s interpretation of the Law.','[{\"title\":\"Pauline Theology\",\"text\":\"Understand the universal concept of sin and faith\"},{\"title\":\"Legal Analysis\",\"text\":\"Examine Paul\'s interpretation of the Law\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate Religious Studies students\"},{\"question\":\"Prerequisites?\",\"answer\":\"None\"},{\"question\":\"Format?\",\"answer\":\"Lectures and readings\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(56,3,48,6,19,1,1,'The God of Community: Ethics, Charisma, and Social Order','Analyzes Paul\'s pastoral and ethical instruction to a divided church. Focuses on the concept of God\'s wisdom revealed in the cross.','New Testament','NT211','the-god-of-community-ethics-charisma-and-social-order','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Ethical Insight\",\"value\":\"Understand early church ethical dynamics\"},{\"name\":\"Social Context\",\"value\":\"Analyze Hellenistic urban society\"}]','2026-02-01','Analyzes Paul\'s pastoral and ethical instruction to a divided church. Focuses on the concept of God\'s wisdom being paradoxically revealed in the cross and the sociological source of conflict within a Hellenistic urban center (e.g., status, spiritual gifts, litigation).','[{\"title\":\"Church Ethics\",\"text\":\"Explore pastoral and ethical teachings\"},{\"title\":\"Conflict Analysis\",\"text\":\"Understand sociological conflicts\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate Religious Studies students\"},{\"question\":\"Prerequisites?\",\"answer\":\"None\"},{\"question\":\"Format?\",\"answer\":\"Lectures and discussions\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(57,3,48,6,19,1,1,'The God of Weakness: Apostolic Authority and Suffering','Examines Paul\'s defense of his ministry. Focuses on God\'s power made perfect in human weakness.','New Testament','NT221','the-god-of-weakness-apostolic-authority-and-suffering','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Theological Insight\",\"value\":\"Understand strength in weakness\"},{\"name\":\"Leadership Skills\",\"value\":\"Examine apostolic authority\"}]','2026-02-01','Examines Paul\'s defense of his ministry. Focuses on the concept of God\'s power being made perfect in human weakness and the rhetorical source of Paul\'s passionate self-justification against competing apostles. Analyzes the socio-historical challenge to his authority.','[{\"title\":\"Apostolic Leadership\",\"text\":\"Study authority and defense of ministry\"},{\"title\":\"Human Weakness\",\"text\":\"Explore theological significance of weakness\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate Religious Studies students\"},{\"question\":\"Prerequisites?\",\"answer\":\"None\"},{\"question\":\"Format?\",\"answer\":\"Lectures and discussion\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(58,3,48,6,19,1,1,'The God of Freedom: Justification and the End of the Law','A study of the theological debate over circumcision and the Law. Focuses on God\'s singular commitment to the covenant of promise.','New Testament','NT231','the-god-of-freedom-justification-and-the-end-of-the-law','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Legal Theology\",\"value\":\"Study law and covenant\"},{\"name\":\"Ethical Insight\",\"value\":\"Understand justification and freedom\"}]','2026-02-01','A study of the fierce theological debate over circumcision and the Law. Focuses on the concept of God\'s singular commitment to the covenant of promise over the covenant of law. Examines the historical friction between Jewish and Gentile Christians.','[{\"title\":\"Covenant Study\",\"text\":\"Examine promise versus law\"},{\"title\":\"Theological Debate\",\"text\":\"Analyze circumcision controversies\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate Religious Studies students\"},{\"question\":\"Prerequisites?\",\"answer\":\"None\"},{\"question\":\"Format?\",\"answer\":\"Lectures and readings\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(59,3,48,6,19,1,1,'The God of Cosmic Unity: Church, Household, and Heavenly Plan','Focuses on God\'s plan (mysterion) to unite all things in Christ, with the church as the new, unified entity.','New Testament','NT241','The-God-of-Cosmic-Unity-Church-Household-and-Heavenly-Plan','339',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Theological Insight\",\"value\":\"Understand cosmic unity in Christ\"},{\"name\":\"Sociological Analysis\",\"value\":\"Study household codes\"}]','2026-02-01','Focuses on the high-level concept of God\'s plan (mysterion) to unite all things in Christ, with the church as the new, unified entity. Analyzes the sociological sources of the \"household codes\" and the influence of Hellenistic concepts of the cosmos.','[{\"title\":\"Cosmic Unity\",\"text\":\"Explore God\'s plan for all things\"},{\"title\":\"Church Structure\",\"text\":\"Analyze household codes\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate Religious Studies students\"},{\"question\":\"Prerequisites?\",\"answer\":\"None\"},{\"question\":\"Format?\",\"answer\":\"Lectures and discussion\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 03:37:01'),
(60,3,48,6,19,1,1,'The Humble God: Christ\'s Kenosis and the Ethics of Humility','A textual and rhetorical analysis of the Christ Hymn (2:5-11), focusing on kenosis','NT','NT251','The-Humble-God-Christs-Kenosis-and-the-Ethics-of-Humility','340',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Spiritual Insight\",\"value\":\"Understand the ethical implications of kenosis\"},{\"name\":\"Textual Analysis\",\"value\":\"Examine the Christ Hymn in historical context\"}]','2026-02-01','A textual and rhetorical analysis of the \"Christ Hymn\" (2:5-11), focusing on the concept of God\'s Son willingly emptying himself (kenosis). Examines the historical context of a mature Christian community under potential external threat.','[{\"title\":\"Kenosis Concept\",\"text\":\"Learn how self-emptying defines Christ\'s mission\"},{\"title\":\"Ethical Application\",\"text\":\"Understand the moral implications for Christian life\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate students in Religious Studies\"},{\"question\":\"Are prior courses required?\",\"answer\":\"No prerequisites required\"},{\"question\":\"What is the assessment method?\",\"answer\":\"Research paper and class discussion\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 03:39:41'),
(61,3,48,6,19,1,1,'The Supreme God: Christ as the Head of All Principalities','Examines the concept of Christ\'s absolute supremacy over all spiritual forces','NT','NT301','The-Supreme-God-Christ-as-the-Head-of-All-Principalities','338',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Cosmic Authority\",\"value\":\"Understand Christ\'s supremacy over spiritual powers\"},{\"name\":\"Theological Analysis\",\"value\":\"Examine doctrinal implications of principalities\"}]','2026-02-01','Examines the concept of Christ\'s absolute supremacy over all spiritual forces, addressing a potential \"heresy\" of angel worship. Focuses on the philosophical/theological source of Christ as the cosmic agent of creation and reconciliation.','[{\"title\":\"Christology\",\"text\":\"Study the theological role of Christ as cosmic agent\"},{\"title\":\"Heresy Examination\",\"text\":\"Analyze historical doctrinal challenges\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate students\"},{\"question\":\"Any prerequisites?\",\"answer\":\"None\"},{\"question\":\"Assessment type?\",\"answer\":\"Essay and discussion\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 03:26:53'),
(62,3,48,6,19,1,1,'The God of the Parousia: Eschatology and Moral Conduct','Focuses on the imminence of the Parousia and God\'s ultimate justice','NT','NT311','The-God-of-the-Parousia-Eschatology-and-Moral-Conduct','341',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Eschatological Insight\",\"value\":\"Understand the Parousia and ethical teachings\"},{\"name\":\"Moral Analysis\",\"value\":\"Examine moral conduct in early Christian communities\"}]','2026-02-01','Analyzes the earliest surviving letter of Paul. Focuses on the imminence of the Parousia (Christ\'s second coming) and the concept of God\'s ultimate justice. Examines the historical context of a new community trying to cope with the deaths of believers before the return.','[{\"title\":\"Eschatology\",\"text\":\"Study beliefs about Christ\'s return\"},{\"title\":\"Moral Conduct\",\"text\":\"Learn ethical implications in early communities\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate students\"},{\"question\":\"Are prerequisites needed?\",\"answer\":\"No\"},{\"question\":\"Assessment type?\",\"answer\":\"Research essay\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 03:54:13'),
(63,3,48,6,19,1,1,'The God of Order: Clarifying the End Times and Social Idleness','Examines the shift in eschatological focus and social discipline','NT','NT321','The-God-of-Order-Clarifying-the-End-Times-and-Social-Idleness','348',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Eschatological Analysis\",\"value\":\"Understand end times in Pauline context\"},{\"name\":\"Social Ethics\",\"value\":\"Study social discipline teachings\"}]','2026-02-01','Examines the shift in eschatological focus, introducing the \"man of lawlessness\" and a delay in the Parousia. Focuses on the concept of a God who maintains social order and discipline. Analyzes the historical-sociological source of problems with idleness.','[{\"title\":\"End Times\",\"text\":\"Learn about eschatological teachings\"},{\"title\":\"Social Order\",\"text\":\"Understand social discipline implications\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate students\"},{\"question\":\"Any prerequisites?\",\"answer\":\"None\"},{\"question\":\"Assessment?\",\"answer\":\"Essay and participation\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 04:17:38'),
(64,3,48,6,19,1,1,'The God of Sound Doctrine: Order, Heresy, and Church Structure','Analysis of the Pastoral Epistles emphasizing sound doctrine','NT','NT331','The-God-of-Sound-Doctrine-Order-Heresy-and-Church-Structure','349',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Doctrinal Study\",\"value\":\"Understand preservation of sound doctrine\"},{\"name\":\"Church Structure\",\"value\":\"Analyze hierarchical leadership\"}]','2026-02-01','An analysis of the Pastoral Epistles. Focuses on the concept of God as the source of \"sound doctrine\" that must be preserved through hierarchical church structure. Examines the historical transition from charismatic to institutional church leadership.','[{\"title\":\"Doctrine\",\"text\":\"Study the importance of sound doctrine\"},{\"title\":\"Church Leadership\",\"text\":\"Understand structural changes in early church\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate students\"},{\"question\":\"Prerequisites?\",\"answer\":\"None\"},{\"question\":\"Assessment?\",\"answer\":\"Essay\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 04:21:27'),
(65,3,48,6,19,1,1,'The God of Perseverance: Legacy, Suffering, and the Deposit of Faith','Paul\'s final testament, emphasizing endurance and faith','NT','NT341','The-God-of-Perseverance-Legacy-Suffering-and-the-Deposit-of-Faith','350',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Perseverance\",\"value\":\"Learn about enduring suffering in faith\"},{\"name\":\"Legacy\",\"value\":\"Understand apostolic succession and teaching\"}]','2026-02-01','Paul\'s final testament. Focuses on the concept of God’s call to endure suffering and maintain the \"good deposit\" of the Gospel. Analyzes the rhetorical source of the writing as a call for a successor to carry on the apostolic mission.','[{\"title\":\"Endurance\",\"text\":\"Understand perseverance in faith\"},{\"title\":\"Apostolic Legacy\",\"text\":\"Learn about succession of teaching\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate students\"},{\"question\":\"Prerequisites?\",\"answer\":\"None\"},{\"question\":\"Assessment?\",\"answer\":\"Essay\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 04:25:42'),
(66,3,48,6,19,1,1,'The God of Good Deeds: Leadership, Ethics, and Community Image','Focuses on God\'s grace leading to ethical behavior and good citizenship','NT','NT351','The-God-of-Good-Deeds-Leadership-Ethics-and-Community-Image','351',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Ethics\",\"value\":\"Learn ethical leadership in the community\"},{\"name\":\"Grace\",\"value\":\"Understand practical implications of God\'s grace\"}]','2026-02-01','Focuses on the concept of God’s grace leading to ethical behavior and good citizenship. Examines the historical necessity of establishing reputable elders/bishops to maintain the church’s witness to the surrounding culture on the island of Crete.','[{\"title\":\"Leadership\",\"text\":\"Learn ethical behavior and governance\"},{\"title\":\"Community Image\",\"text\":\"Understand church witness in society\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate students\"},{\"question\":\"Prerequisites?\",\"answer\":\"None\"},{\"question\":\"Assessment?\",\"answer\":\"Essay and participation\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 04:28:33'),
(67,3,48,6,19,1,1,'The God of Reconciliation: Slavery, Hierarchy, and Brotherhood','A socio-rhetorical analysis of early Christian reconciliation','NT','NT401','The-God-of-Reconciliation-Slavery-Hierarchy-and-Brotherhood','354',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Reconciliation\",\"value\":\"Understand social and spiritual reconciliation\"},{\"name\":\"Ethics\",\"value\":\"Study hierarchical relationships in early church\"}]','2026-02-01','A socio-rhetorical analysis of this brief letter. Focuses on the concept of God as the one who dismantles social barriers by making a slave (Onesimus) a \"brother\" in Christ. Examines the historical institution of slavery in the Roman world.','[{\"title\":\"Social Justice\",\"text\":\"Understand reconciliation in society\"},{\"title\":\"Church Hierarchy\",\"text\":\"Learn about relationships within early church\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate students\"},{\"question\":\"Any prerequisites?\",\"answer\":\"None\"},{\"question\":\"Assessment?\",\"answer\":\"Essay\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 04:36:03'),
(68,3,48,6,19,1,1,'The Superior God: Christ as the Great High Priest and Final Word','Explores Christ as final and ultimate revelation','NT','NT411','the-superior-god-christ-as-the-great-high-priest-and-final-word','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Christology\",\"value\":\"Understand Christ\'s final authority\"},{\"name\":\"Theological Analysis\",\"value\":\"Study the role of Christ as High Priest\"}]','2026-02-01','A rhetorical masterpiece that focuses on the concept of God having spoken ultimately and finally through Christ, who is superior to the prophets, angels, and the entire Mosaic system. Analyzes the source of the author’s use of Platonic ideals and Jewish Temple theology.','[{\"title\":\"High Priest\",\"text\":\"Study Christ\'s role as High Priest\"},{\"title\":\"Ultimate Word\",\"text\":\"Understand finality of revelation\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate students\"},{\"question\":\"Prerequisites?\",\"answer\":\"None\"},{\"question\":\"Assessment?\",\"answer\":\"Essay\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(69,3,48,6,19,1,1,'The Practical God: Faith, Works, and the Ethics of Wisdom','Focuses on righteousness expressed through actions','NT','NT421','The-Practical-God-Faith-Works-and-the-Ethics-of-Wisdom','355',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Ethical Application\",\"value\":\"Understand how faith translates into actions\"},{\"name\":\"Practical Wisdom\",\"value\":\"Apply biblical wisdom to life\"}]','2026-02-01','A study of the ethical and practical nature of religious life. Focuses on the concept of a God whose righteousness must be expressed through concrete actions, critiquing a purely intellectual or \"dead\" faith. Examines its source in Jewish wisdom literature.','[{\"title\":\"Faith in Action\",\"text\":\"Learn how to apply righteousness practically\"},{\"title\":\"Wisdom Ethics\",\"text\":\"Understand ethical living principles\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate students\"},{\"question\":\"Prerequisites?\",\"answer\":\"None\"},{\"question\":\"Assessment?\",\"answer\":\"Essay and participation\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 04:43:24'),
(70,3,48,6,19,1,1,'The God of Hope: Pilgrimage, Suffering, and Baptismal Identity','Explores the concept of God calling believers to be \"aliens and exiles\" in a hostile world','NT','NT431','The-God-of-Hope-Pilgrimage-Suffering-and-Baptismal-Identity','358',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Spiritual Resilience\",\"value\":\"Learn how hope sustains believers through suffering\"},{\"name\":\"Identity Formation\",\"value\":\"Understand baptismal identity in hostile contexts\"}]','2026-02-01','Examines the concept of a God who calls believers to be \"aliens and exiles\" in a hostile world. Focuses on the historical context of sporadic persecution and the theological source of finding identity and strength in the suffering of Christ.','[{\"title\":\"Pilgrimage and Exile\",\"text\":\"Understand Christian identity as spiritual pilgrimage\"},{\"title\":\"Strength in Suffering\",\"text\":\"Learn theological implications of hope in adversity\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate students\"},{\"question\":\"Are prerequisites required?\",\"answer\":\"No\"},{\"question\":\"How will assessment be done?\",\"answer\":\"Essay and class participation\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 05:04:27'),
(71,3,48,6,19,1,1,'The God of Delayed Judgment: False Teaching and Cosmic Destruction','Explores God\'s patience in delaying judgment and cosmic purification','NT','NT441','The-God-of-Delayed-Judgment-False-Teaching-and-Cosmic-Destruction','359',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Patience in Theology\",\"value\":\"Understand God\'s timing and patience\"},{\"name\":\"Apocalyptic Insight\",\"value\":\"Analyze the cosmic justice motif\"}]','2026-02-01','Focuses on the concept of God\'s patience (makrothymia) in delaying the Parousia and the coming cosmic purification by fire. Analyzes the historical polemic against internal false teachers and the source of the author\'s reliance on apocalyptic and non-canonical Jewish texts.','[{\"title\":\"God\'s Patience\",\"text\":\"Study theological rationale of delayed judgment\"},{\"title\":\"Cosmic Purification\",\"text\":\"Examine apocalyptic cleansing themes\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate students\"},{\"question\":\"Prerequisites?\",\"answer\":\"None\"},{\"question\":\"Assessment?\",\"answer\":\"Essay\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 05:17:57'),
(72,3,48,6,19,1,1,'The Moral God: Love, Sin, and the Test of True Community','Explore God\'s moral guidance and the role of love in the community','NT','NT501','The-Moral-God-Love-Sin-and-the-Test-of-True-Community','360',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Ethical Application\",\"value\":\"Understand God\'s ethical framework\"},{\"name\":\"Community Life\",\"value\":\"Analyze principles for authentic Christian living\"}]','2026-02-01','A theological study of the concept of God as \"Light\" and \"Love.\" Focuses on the dualistic test of authentic Christian community: moral behavior (not sinning) and love for one another. Examines the historical context of a split within the Johannine community (proto-Gnosticism).','[{\"title\":\"Moral Integrity\",\"text\":\"Learn how love and morality intersect in faith\"},{\"title\":\"Community Testing\",\"text\":\"Study how early communities were tested by ethical dilemmas\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Undergraduate Religious Studies students\"},{\"question\":\"Course Length?\",\"answer\":\"One semester\"},{\"question\":\"Exams?\",\"answer\":\"Essay\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 05:41:31'),
(73,3,48,6,19,1,1,'The God of Truth: Protecting Doctrine and Apostolic Authority','Exploring the tension between truth and love in early Christian communities','NT','NT511','The-God-of-Truth-Protecting-Doctrine-and-Apostolic-Authority','361',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Strengthen Doctrinal Understanding\",\"value\":\"Learn to discern truth from false teachings in historical and modern contexts\"},{\"name\":\"Community Leadership\",\"value\":\"Understand how to protect shared doctrine within early Christian communities\"}]','2026-02-01','A brief study on the tension between truth (orthodoxy) and love (orthopraxy). Focuses on the concept of God\'s truth being a boundary marker for community and the historical context of traveling missionaries and the protection of the community’s shared doctrine.','[{\"title\":\"Doctrine Analysis\",\"text\":\"Examine key biblical passages that define orthodoxy\"},{\"title\":\"Historical Context\",\"text\":\"Understand the societal challenges faced by early missionaries\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate students in Religious Studies\"},{\"question\":\"Are prior courses required?\",\"answer\":\"No prerequisites are necessary\"},{\"question\":\"Will there be assessments?\",\"answer\":\"Yes, including written reflections and discussions\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 05:42:31'),
(74,3,48,6,19,1,1,'The God of Hospitality: Ministry, Authority, and Church Conflict','Analyzing hospitality and authority in early Christian communities','NT','NT521','The-God-of-Hospitality-Ministry-Authority-and-Church-Conflict','363',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Hospitality Insights\",\"value\":\"Learn the role of hospitality in maintaining church unity\"},{\"name\":\"Conflict Resolution\",\"value\":\"Understand early church power dynamics and leadership challenges\"}]','2026-02-01','A sociological study of the role of hospitality and authority in the early church. Focuses on the concept of God\'s plan being carried out through supporting faithful mission workers and navigating local power struggles (e.g., Diotrephes).','[{\"title\":\"Sociological Analysis\",\"text\":\"Study the interplay between social norms and church authority\"},{\"title\":\"Case Studies\",\"text\":\"Examine historical examples of conflict resolution in early Christian communities\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate students in Religious Studies\"},{\"question\":\"Is prior knowledge required?\",\"answer\":\"No, open to all undergraduates\"},{\"question\":\"How will students be assessed?\",\"answer\":\"Participation and written assignments\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 05:47:02'),
(75,3,48,6,19,1,1,'The God Who Contends: Defense of the Faith and Canonical Dissent','Defending apostolic teaching against corruption and dissent','NT','NT531','the-god-who-contends-defense-of-the-faith-and-canonical-dissent','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Faith Defense\",\"value\":\"Equip yourself to defend original apostolic teaching\"},{\"name\":\"Canonical Understanding\",\"value\":\"Analyze controversial Jewish apocalyptic literature and canonical issues\"}]','2026-02-01','An urgent call to defend the original apostolic teaching against moral and doctrinal corruption. Focuses on the concept of God as the ultimate judge who will punish the ungodly. Analyzes the author\'s controversial source material from Jewish apocalyptic literature.','[{\"title\":\"Critical Analysis\",\"text\":\"Learn to critically evaluate sources and doctrinal claims\"},{\"title\":\"Moral Application\",\"text\":\"Understand ethical implications of apostolic teachings\"}]','[{\"question\":\"Who should take this course?\",\"answer\":\"Undergraduate students in NT studies\"},{\"question\":\"Are readings required?\",\"answer\":\"Yes, primary and secondary source readings\"},{\"question\":\"Will there be exams?\",\"answer\":\"Yes, short written assessments\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(76,3,48,6,19,1,1,'The Sovereign God: Eschatology, Empire, and the New Jerusalem','Exploring divine sovereignty and apocalyptic literature in early Christianity','NT','NT601','The-Sovereign-God-Eschatology-Empire-and-the-New-Jerusalem','371',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Eschatological Insight\",\"value\":\"Understand God as Pantokrator and His judgment over empires\"},{\"name\":\"Historical Context\",\"value\":\"Examine persecution under Domitian and apocalyptic literature\"}]','2026-02-01','A literary and historical analysis of Christian apocalyptic literature. Focuses on the concept of God as the absolute, sovereign ruler (Pantokrator) who judges the oppressive Roman Empire (\"Babylon\") and establishes the eternal \"New Jerusalem.\" Examines the historical context of Imperial persecution under Domitian.','[{\"title\":\"Literary Analysis\",\"text\":\"Study the apocalyptic texts and symbolism\"},{\"title\":\"Historical Context\",\"text\":\"Understand Roman Empire context and Christian persecution\"}]','[{\"question\":\"Who is this course for?\",\"answer\":\"Undergraduate students interested in eschatology\"},{\"question\":\"Is prior knowledge needed?\",\"answer\":\"Basic understanding of NT recommended\"},{\"question\":\"Are there written assignments?\",\"answer\":\"Yes, textual analysis papers\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 06:19:08'),
(77,3,15,6,19,1,1,'The God of Military Nationalism: Hellenism and Jewish Resistance','A historical-critical study of the Maccabean Revolt and divine national defense','APOC','APOC101','The-God-of-Military-Nationalism-Hellenism-and-Jewish-Resistance','373',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Historical Insight\",\"value\":\"Understand the Maccabean Revolt and Jewish resistance under Hellenistic rule\"},{\"name\":\"Divine Nationalism\",\"value\":\"Explore God\'s role as a militant defender in covenant history\"}]','2026-02-01','A historical-critical study of the Maccabean Revolt. Focuses on the concept of God as a militant, national defender whose covenant is affirmed through armed conflict and resistance to Hellenization. Examines the historical context of Seleucid rule (2nd century BCE).','[{\"title\":\"Historical Analysis\",\"text\":\"Examine Seleucid policies and Jewish responses\"},{\"title\":\"Theological Perspective\",\"text\":\"Understand the covenantal significance of armed resistance\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate students in Religious Studies interested in Jewish history and theology.\"},{\"question\":\"Are prior courses required?\",\"answer\":\"No prerequisites, though knowledge of Old Testament history is helpful.\"},{\"question\":\"Will there be assessments?\",\"answer\":\"Yes, including essays and class discussions analyzing historical and theological themes.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 06:20:05'),
(78,3,15,6,19,1,1,'God and Martyrdom: Resurrection and Creative Justice','Exploring resurrection theology and hope under persecution','APOC','APOC111','God-and-Martyrdom-Resurrection-and-Creative-Justice','383',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Theological Insight\",\"value\":\"Analyze resurrection and creation ex nihilo as sources of hope for martyrs\"},{\"name\":\"Historical Context\",\"value\":\"Understand persecution and post-Exilic Jewish theology development\"}]','2026-02-01','Analyzes the theological shift towards resurrection and creation ex nihilo (from nothing) as a source of hope for martyrs. Examines the historical context of persecution and the development of post-Exilic Jewish theology in the face of Hellenistic oppression.','[{\"title\":\"Theological Analysis\",\"text\":\"Examine concepts of resurrection and divine justice in Jewish thought\"},{\"title\":\"Historical Study\",\"text\":\"Explore Hellenistic oppression and its effect on Jewish theological development\"}]','[{\"question\":\"Who should take this course?\",\"answer\":\"Undergraduate students in Religious Studies focusing on Jewish and apocalyptic theology.\"},{\"question\":\"Are there readings required?\",\"answer\":\"Yes, primary and secondary texts will be studied to understand theological shifts.\"},{\"question\":\"Will students be assessed?\",\"answer\":\"Yes, through written reflections and research essays on theological topics.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 07:03:35'),
(79,3,15,6,19,1,1,'The God of the Unexpected Heroine: Ethics and Gender in War','Literary analysis of unconventional women as instruments of divine deliverance','APOC','APOC121','The-God-of-the-Unexpected-Heroine-Ethics-and-Gender-in-War','387',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Ethical and Gender Studies\",\"value\":\"Explore the role of women in post-Exilic narratives and ethical implications of divine action\"},{\"name\":\"Literary Insight\",\"value\":\"Analyze narrative techniques highlighting resourceful, unconventional women in biblical stories\"}]','2026-02-01','A literary analysis of the fictional narrative. Focuses on the concept of God using a resourceful, unconventional woman to deliver Israel. Examines the theological source of \"pious violence\" and the role of women in Post-Exilic narrative.','[{\"title\":\"Literary Analysis\",\"text\":\"Understand narrative structures and characterization of women\"},{\"title\":\"Ethical Reflection\",\"text\":\"Discuss theological and moral lessons from unconventional divine interventions\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate students interested in biblical narratives, gender studies, and ethics.\"},{\"question\":\"Are prior courses necessary?\",\"answer\":\"No, but familiarity with Old Testament narratives is recommended.\"},{\"question\":\"How will students be assessed?\",\"answer\":\"Through analytical essays and classroom discussions on ethics and gender in biblical texts.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 07:12:58'),
(80,3,15,6,19,1,1,'The God of the Diaspora: Angels, Demons, and Family Piety','Exploring divine providence, angelic activity, and folk demonology in Jewish exile','APOC','APOC131','The-God-of-the-Diaspora-Angels-Demons-and-Family-Piety','389',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Providential Insight\",\"value\":\"Understand God\'s intervention in daily life through angels and divine guidance\"},{\"name\":\"Demonology Studies\",\"value\":\"Examine historical sources of Asmodeus and early Jewish beliefs about spiritual beings\"}]','2026-02-01','Focuses on the concept of God\'s providence operating through angels (Raphael) in the daily life of a Jewish family in exile. Examines the historical setting of the Diaspora and the folk-religious source of demonology (Asmodeus) in early Judaism.','[{\"title\":\"Angelic Intervention\",\"text\":\"Study Raphael\'s role in guiding the faithful and family protection\"},{\"title\":\"Historical Context\",\"text\":\"Understand the Diaspora environment and Jewish piety practices\"}]','[{\"question\":\"Who is this course suitable for?\",\"answer\":\"Undergraduate students in Religious Studies or those interested in Jewish history and angelology, especially regarding the Diaspora experience.\"},{\"question\":\"Will prior knowledge of Jewish texts help?\",\"answer\":\"While helpful, prior knowledge is not required as key texts and historical background will be provided in the course materials.\"},{\"question\":\"How will the course handle theological complexity?\",\"answer\":\"Complex ideas about angels, demons, and divine providence will be explained with historical examples and practical interpretation to facilitate understanding.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 07:18:57'),
(81,3,15,6,19,1,1,'God and Divine Sophia: Platonic Philosophy and Immortality','Studying God\'s nature through wisdom, Platonic philosophy, and Hellenistic Jewish thought','APOC','APOC141','God-and-Divine-Sophia-Platonic-Philosophy-and-Immortality','390',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Philosophical Insight\",\"value\":\"Explore God\'s wisdom (Sophia) in relation to Platonic ideals of immortality and the soul\"},{\"name\":\"Hellenistic Context\",\"value\":\"Understand Jewish-Greek thought synthesis in Alexandria and its theological implications\"}]','2026-02-01','A philosophical study of God’s nature revealed through Sophia (Wisdom). Focuses on the source blending of Greek Platonic ideals (immortality of the soul) with Jewish wisdom traditions, placed in the Hellenistic context of Alexandria (1st century BCE).','[{\"title\":\"Philosophical Foundations\",\"text\":\"Examine the integration of Platonic immortality concepts with Jewish wisdom theology\"},{\"title\":\"Historical Setting\",\"text\":\"Study Alexandria as a cultural and intellectual center influencing Jewish philosophical thought\"}]','[{\"question\":\"Who can benefit from this course?\",\"answer\":\"Undergraduate students interested in Jewish philosophy, Hellenistic thought, and the theological concept of Sophia.\"},{\"question\":\"Are prior philosophy courses required?\",\"answer\":\"No prerequisites are needed, but basic familiarity with Greek philosophy is helpful to contextualize the content.\"},{\"question\":\"Will students analyze texts?\",\"answer\":\"Yes, students will read and interpret key Jewish and Platonic texts to understand philosophical and theological concepts.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 07:28:35'),
(82,3,15,6,19,1,1,'The Practical God: Wisdom, Social Ethics, and Temple Authority','Understanding God as the source of social order and Torah-based wisdom','APOC','APOC151','the-practical-god-wisdom-social-ethics-and-temple-authority','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Social and Ethical Insight\",\"value\":\"Examine God\'s guidance for social and cosmic order through wisdom and Torah\"},{\"name\":\"Temple Authority\",\"value\":\"Understand the role of the Jerusalem sage and the administration of religious practice\"}]','2026-02-01','Focuses on the conservative concept of God as the source of a predictable social and cosmic order. Examines the source of wisdom in the Torah and the role of the Jerusalem sage in the 2nd century BCE, contrasting with the philosophical sweep of the Wisdom of Solomon.','[{\"title\":\"Wisdom Studies\",\"text\":\"Analyze Torah texts to understand ethical and social guidelines\"},{\"title\":\"Authority Structures\",\"text\":\"Explore the role of temple leadership in maintaining order and teaching wisdom\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Undergraduate students in Religious Studies with interest in Jewish ethics, Torah studies, and social theology.\"},{\"question\":\"Is prior knowledge of the Torah necessary?\",\"answer\":\"Not required, key excerpts and explanations will be provided for context.\"},{\"question\":\"How will students be evaluated?\",\"answer\":\"Through essays, discussion participation, and analysis of ethical case studies drawn from historical texts.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(83,3,15,6,19,1,1,'The God of Repentance: Confession of Sins and Hope for Return','Studies the book as a communal confession of sin in exile','APOC','APOC 201','the-god-of-repentance-confession-of-sins-and-hope-for-return','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Exegetical Skills\",\"value\":\"Learn to analyze communal confession texts in their historical context\"},{\"name\":\"Theological Insight\",\"value\":\"Understand the concepts of divine patience and covenant restoration\"}]','2026-02-01','Studies the book as a communal confession of sin in exile. Focuses on the concept of God\'s patience and the pathway back to covenant blessing. Analyzes the historical context following the Babylonian destruction and the source in Jeremiah\'s prophecy.','[{\"title\":\"Historical Analysis\",\"text\":\"Examine post-Babylonian destruction context\"},{\"title\":\"Prophetic Connection\",\"text\":\"Analyze Jeremiah\'s prophecy as source material\"}]','[{\"question\":\"What is the main focus of this course?\",\"answer\":\"This course focuses on the book as a communal confession of sin during the exile period, examining God\'s patience and the path to covenant restoration.\"},{\"question\":\"Who should take this course?\",\"answer\":\"Undergraduate students in Religious Studies or anyone interested in exilic literature and themes of repentance in biblical texts.\"},{\"question\":\"What background knowledge is required?\",\"answer\":\"Basic familiarity with Old Testament history and prophetic literature is helpful but not required.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(84,3,15,6,19,1,1,'The True God vs. Idolatry: A Polemic on Babylonian Worship','An analysis of the book as a warning against the temptation of paganism in exile','APOC','APOC 211','the-true-god-vs-idolatry-a-polemic-on-babylonian-worship','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Comparative Analysis\",\"value\":\"Learn to contrast living God concepts with pagan idolatry\"},{\"name\":\"Rhetorical Skills\",\"value\":\"Understand satire and polemic techniques in diaspora literature\"}]','2026-02-01','An analysis of the book as a warning against the temptation of paganism in exile. Focuses on the contrast between the living God and the futility of idols. Examines the rhetorical source of satire and polemic in the diaspora community.','[{\"title\":\"Idolatry Analysis\",\"text\":\"Examine contrasts between divine concepts and pagan worship\"},{\"title\":\"Rhetorical Study\",\"text\":\"Analyze satire and polemic techniques in diaspora texts\"}]','[{\"question\":\"What theological contrast does this course explore?\",\"answer\":\"The course explores the contrast between the living God of Israel and the futility of Babylonian idols during the exile period.\"},{\"question\":\"What literary techniques are examined?\",\"answer\":\"Students will analyze satire and polemic as rhetorical devices used in diaspora community literature.\"},{\"question\":\"How is this course relevant today?\",\"answer\":\"The themes of resisting cultural assimilation and maintaining religious identity remain relevant in contemporary contexts.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(85,3,15,6,19,1,1,'God and Liturgical Piety: Prayer, Ordeal, and Ethical Integrity','Examines the Prayer of Azariah and Susanna, focusing on the concept of God as the vindicator','APOC','APOC 221','god-and-liturgical-piety-prayer-ordeal-and-ethical-integrity','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Devotional Analysis\",\"value\":\"Study prayer and liturgical additions to biblical texts\"},{\"name\":\"Ethical Framework\",\"value\":\"Understand God\'s role as vindicator of the innocent\"}]','2026-02-01','Examines the Prayer of Azariah and Susanna, focusing on the concept of God as the vindicator of the innocent in the face of legal or physical threat. Analyzes the source of these devotional additions to enhance the book\'s piety.','[{\"title\":\"Textual Additions\",\"text\":\"Study devotional enhancements to biblical narratives\"},{\"title\":\"Vindication Theology\",\"text\":\"Examine God\'s role in protecting the innocent\"}]','[{\"question\":\"Which specific texts are examined in this course?\",\"answer\":\"The course focuses on the Prayer of Azariah and the story of Susanna from the Apocryphal additions to Daniel.\"},{\"question\":\"What theological concept is central to this study?\",\"answer\":\"The central concept is God as the vindicator and protector of innocent people facing unjust threats or legal challenges.\"},{\"question\":\"What is the historical context of these additions?\",\"answer\":\"These devotional additions were created to enhance the piety and theological depth of the original biblical narratives during the Second Temple period.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(86,3,15,6,19,1,1,'The Explicit God: Divine Intervention in the Secular Narrative','Studies the theological function of the additions which explicitly insert God into the book of Esther','APOC','APOC 231','the-explicit-god-divine-intervention-in-the-secular-narrative','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Textual Criticism\",\"value\":\"Learn to analyze canonical and non-canonical variants\"},{\"name\":\"Theological Interpretation\",\"value\":\"Understand the need for divine clarity in diaspora stories\"}]','2026-02-01','Studies the theological function of the additions (prayers, dreams, royal letters) which explicitly insert God into the book of Esther, where the canonical text omits God\'s name. Focuses on the source need for divine clarity in a diaspora story.','[{\"title\":\"Divine Insertion\",\"text\":\"Examine theological additions to the Esther narrative\"},{\"title\":\"Diaspora Theology\",\"text\":\"Study the need for explicit divine presence\"}]','[{\"question\":\"Why does the canonical book of Esther not mention God?\",\"answer\":\"The canonical version is unique in not explicitly mentioning God, which led to later additions to make divine involvement clearer.\"},{\"question\":\"What types of additions are studied?\",\"answer\":\"Students examine prayers, dreams, and royal letters added to later versions of Esther that explicitly mention God\'s intervention.\"},{\"question\":\"What does this reveal about diaspora theology?\",\"answer\":\"The additions reveal a theological need to make God\'s presence explicit in stories about Jewish survival in foreign lands.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(87,3,16,6,19,1,1,'The Watchers and the Divine Council: Origins of Evil and Cosmology','A study of the foundational Pseudepigraphal text on fallen angels and cosmology','PSEUD','PSEUD 301','the-watchers-and-the-divine-council-origins-of-evil-and-cosmology','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Cosmological Study\",\"value\":\"Explore early Jewish cosmology and angelology\"},{\"name\":\"Influence Analysis\",\"value\":\"Trace Pseudepigraphal impact on New Testament concepts\"}]','2026-02-01','A study of the foundational Pseudepigraphal text. Focuses on the concept of God as the supreme ruler who judges the fallen angels (Watchers), providing a source for the origins of evil, demonology, and Messianic expectations influential in the New Testament period.','[{\"title\":\"Angelology\",\"text\":\"Study the Watchers and fallen angel traditions\"},{\"title\":\"Cosmological Origins\",\"text\":\"Examine early Jewish concepts of evil origins\"}]','[{\"question\":\"Who are the Watchers in Pseudepigraphal literature?\",\"answer\":\"The Watchers are fallen angels who descended to earth, taught forbidden knowledge to humanity, and fathered the Nephilim, according to 1 Enoch and other texts.\"},{\"question\":\"How did these texts influence New Testament theology?\",\"answer\":\"Concepts of demonology, messianic expectations, and cosmological frameworks from Pseudepigraphal texts significantly influenced New Testament writers and early Christian thought.\"},{\"question\":\"Why are these texts considered Pseudepigrapha?\",\"answer\":\"They are attributed to ancient biblical figures but were written later, during the Second Temple period, and were not included in the Hebrew canon.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(88,3,16,6,19,1,1,'The Hierarchical God: Celestial Journeys and Creation','Focuses on the concept of a hierarchical God who reveals cosmic secrets','PSEUD','PSEUD 311','the-hierarchical-god-celestial-journeys-and-creation','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Mystical Tradition\",\"value\":\"Explore early Jewish mystical speculation\"},{\"name\":\"Cosmological Mapping\",\"value\":\"Study multi-tiered heaven concepts and their development\"}]','2026-02-01','Focuses on the concept of a hierarchical God who reveals the secrets of the cosmos through a multi-tiered heaven. Examines the source of early Jewish mystical and cosmological speculation and its influence on later apocalyptic literature.','[{\"title\":\"Celestial Structure\",\"text\":\"Examine multi-tiered heaven concepts\"},{\"title\":\"Mystical Revelation\",\"text\":\"Study divine secret transmission methods\"}]','[{\"question\":\"What is meant by hierarchical God in this context?\",\"answer\":\"This refers to God revealing cosmic secrets through layered celestial structures and angelic intermediaries in Pseudepigraphal texts.\"},{\"question\":\"How did these texts influence later literature?\",\"answer\":\"Early Jewish mystical speculation directly influenced both Jewish Merkabah mysticism and early Christian apocalyptic literature.\"},{\"question\":\"What are key texts studied in this course?\",\"answer\":\"Primary texts include 2 Enoch, the Apocalypse of Abraham, and other Pseudepigraphal works featuring celestial journeys.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(89,3,16,6,19,1,1,'The Calendar and the Exclusive God: Law, Time, and Covenant Purity','Focuses on God demanding adherence to a specific solar calendar and absolute purity','PSEUD','PSEUD 321','the-calendar-and-the-exclusive-god-law-time-and-covenant-purity','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Calendar Studies\",\"value\":\"Understand solar vs. lunar calendar controversies\"},{\"name\":\"Sectarian Analysis\",\"value\":\"Study Qumran community\'s break from mainstream Judaism\"}]','2026-02-01','Focuses on the concept of God demanding adherence to a specific, solar calendar and absolute purity. Analyzes the source of sectarian law and its historical context among groups like the Qumran community (Dead Sea Scrolls) who broke from the Jerusalem cult.','[{\"title\":\"Calendar Controversy\",\"text\":\"Examine solar calendar sectarian practices\"},{\"title\":\"Purity Laws\",\"text\":\"Study absolute purity requirements in sectarian groups\"}]','[{\"question\":\"Why was calendar observance so important to sectarian groups?\",\"answer\":\"Calendar observance marked theological identity and separation, with different calendars symbolizing different understandings of covenant fidelity.\"},{\"question\":\"How do the Dead Sea Scrolls relate to this course?\",\"answer\":\"The Qumran community, which produced the Dead Sea Scrolls, rigorously followed a solar calendar and strict purity laws in opposition to the Jerusalem temple establishment.\"},{\"question\":\"What theological implications did calendar differences have?\",\"answer\":\"Calendar differences created separate holy days and worship times, effectively creating parallel religious communities with different liturgical rhythms.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(90,3,16,6,19,1,1,'The God of Ethical Wills: Moral Instruction and Prophetic Legacy','Examines ethical instruction supposedly given by Jacob\'s sons','PSEUD','PSEUD 331','the-god-of-ethical-wills-moral-instruction-and-prophetic-legacy','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Ethical Analysis\",\"value\":\"Study testamentary literature and moral instruction\"},{\"name\":\"Character Study\",\"value\":\"Examine patriarchal ethics and family dynamics\"}]','2026-02-01','Examines the source material as ethical instruction supposedly given by Jacob\'s sons. Focuses on the concept of God revealing moral failures and the path to repentance, highlighting ethical themes like jealousy and sincerity.','[{\"title\":\"Testamentary Form\",\"text\":\"Study ethical instruction through final speeches\"},{\"title\":\"Moral Themes\",\"text\":\"Examine jealousy, repentance, and sincerity\"}]','[{\"question\":\"What are Testamentary or Ethical Wills?\",\"answer\":\"These are Pseudepigraphal texts presented as final ethical instructions from biblical patriarchs to their children before death.\"},{\"question\":\"Which specific texts are studied?\",\"answer\":\"The Testaments of the Twelve Patriarchs, featuring ethical instructions attributed to each of Jacob\'s twelve sons.\"},{\"question\":\"What moral themes predominate in these texts?\",\"answer\":\"Themes include warnings against jealousy (like Joseph\'s brothers), calls to repentance, and instructions for sincere devotion to God.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(91,3,16,6,19,1,1,'The God of Traumatic Theodicy: Judgment on Israel and the End Times','A deep analysis of the problem of evil and Israel\'s suffering after the Temple destruction','PSEUD','PSEUD 341','the-god-of-traumatic-theodicy-judgment-on-israel-and-the-end-times','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Theodicy Study\",\"value\":\"Examine responses to suffering in Jewish literature\"},{\"name\":\"Apocalyptic Analysis\",\"value\":\"Understand end-times speculation after national trauma\"}]','2026-02-01','A deep analysis of the problem of evil and Israel\'s suffering after the destruction of the Temple (70 CE). Focuses on the concept of God\'s plan being incomprehensible and the source of intense anguish over national fate and the timing of the end of the age.','[{\"title\":\"Post-70 CE Trauma\",\"text\":\"Examine theological responses to Temple destruction\"},{\"title\":\"Divine Mystery\",\"text\":\"Study incomprehensible divine plan concepts\"}]','[{\"question\":\"What historical event shapes this literature?\",\"answer\":\"The destruction of the Second Temple in 70 CE created a theological crisis that generated intense apocalyptic literature addressing God\'s seeming abandonment.\"},{\"question\":\"How is theodicy addressed in these texts?\",\"answer\":\"Texts like 4 Ezra and 2 Baruch struggle with why a righteous God would allow such catastrophic suffering to His chosen people.\"},{\"question\":\"What eschatological themes emerge?\",\"answer\":\"Themes include urgent end-times expectation, messianic hope, and attempts to calculate the timing of divine intervention.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(92,3,17,6,19,1,1,'The God of Second Chances: Penitential Doctrine and Church Discipline','An early Christian text focusing on post-baptismal forgiveness for sin','NTAPOC','NTAPOC 401','the-god-of-second-chances-penitential-doctrine-and-church-discipline','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Historical Theology\",\"value\":\"Study early church discipline and forgiveness practices\"},{\"name\":\"Doctrinal Development\",\"value\":\"Trace penitential theology evolution\"}]','2026-02-01','An early Christian text focusing on the concept of God\'s patience and the possibility of post-baptismal forgiveness for sin. Examines the historical context of early church moral debates and the source of its allegorical, visionary style.','[{\"title\":\"Church Discipline\",\"text\":\"Examine early Christian penitential systems\"},{\"title\":\"Post-Baptismal Sin\",\"text\":\"Study theological debates about forgiveness\"}]','[{\"question\":\"What is the main theological issue in this text?\",\"answer\":\"The Shepherd of Hermas addresses whether Christians can receive forgiveness for serious sins committed after baptism.\"},{\"question\":\"How does this reflect early church struggles?\",\"answer\":\"It reveals tension between maintaining moral purity in the community and extending God\'s mercy to failing members.\"},{\"question\":\"What literary style characterizes this text?\",\"answer\":\"The text uses visions, allegories, and angelic revelations (the Shepherd) to convey its penitential message.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(93,3,17,6,19,1,1,'The Teaching God: Apostolic Instruction and Communal Order','Studies this text as the earliest church manual for ethical discipline','NTAPOC','NTAPOC 411','the-teaching-god-apostolic-instruction-and-communal-order','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Early Church Studies\",\"value\":\"Examine primitive Christian community organization\"},{\"name\":\"Liturgical History\",\"value\":\"Study origins of baptism, eucharist, and prayer practices\"}]','2026-02-01','Studies this text as the earliest church manual. Focuses on the concept of God as the source of \"The Two Ways\" (Life and Death) and ethical discipline. Examines the historical source of early communal practice, including baptism, prayer, and eucharist.','[{\"title\":\"Church Manual\",\"text\":\"Study the Didache as earliest Christian handbook\"},{\"title\":\"Two Ways Doctrine\",\"text\":\"Examine ethical teaching framework\"}]','[{\"question\":\"What is the Didache?\",\"answer\":\"The Didache (Teaching of the Twelve Apostles) is an early Christian manual dating to the late 1st century, covering ethics, rituals, and church organization.\"},{\"question\":\"What are The Two Ways?\",\"answer\":\"A foundational ethical framework contrasting the Way of Life (virtues) with the Way of Death (vices), possibly derived from Jewish ethical teaching.\"},{\"question\":\"What practical instructions does it contain?\",\"answer\":\"Instructions for baptism, Eucharist, prayer, fasting, treatment of traveling prophets, and Sunday worship gatherings.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(94,3,17,6,19,1,1,'The God of Hidden Sayings: Esoteric Knowledge and Inner Wisdom','An analysis of sayings collection focusing on secret knowledge and self-discovery','NTAPOC','NTAPOC 421','the-god-of-hidden-sayings-esoteric-knowledge-and-inner-wisdom','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Gnostic Studies\",\"value\":\"Explore non-canonical Christian mystical traditions\"},{\"name\":\"Comparative Religion\",\"value\":\"Contrast gnostic and orthodox Christian approaches\"}]','2026-02-01','An analysis of the sayings collection. Focuses on the concept of God revealing salvation through secret knowledge (gnosis) and self-discovery rather than historical events. Examines the source tradition of non-canonical Gnosticism and its historical break from orthodox Christianity.','[{\"title\":\"Gnostic Tradition\",\"text\":\"Study salvation through secret knowledge\"},{\"title\":\"Sayings Collection\",\"text\":\"Examine Gospel of Thomas format and content\"}]','[{\"question\":\"What is the Gospel of Thomas?\",\"answer\":\"A non-canonical sayings gospel discovered at Nag Hammadi, containing 114 sayings attributed to Jesus, emphasizing secret knowledge and self-discovery.\"},{\"question\":\"How does gnosticism differ from orthodox Christianity?\",\"answer\":\"Gnosticism emphasizes secret knowledge (gnosis) for salvation, often viewing the material world as evil and the spiritual self as divine, contrasting with orthodox emphasis on faith in historical events.\"},{\"question\":\"Why was this text excluded from the canon?\",\"answer\":\"Its gnostic theology, lack of narrative, and different soteriology conflicted with emerging orthodox Christian doctrine centered on Christ\'s death and resurrection.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(95,3,17,6,19,1,1,'The Unfolding God: Narratives of the Passion and Resurrection','Examines non-canonical passion account with dramatic supernatural events','NTAPOC','NTAPOC 431','the-unfolding-god-narratives-of-the-passion-and-resurrection','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Apocryphal Gospels\",\"value\":\"Study non-canonical passion narratives\"},{\"name\":\"Comparative Analysis\",\"text\":\"Contrast canonical and apocryphal resurrection accounts\"}]','2026-02-01','Examines this non-canonical passion account. Focuses on the concept of God revealing Christ\'s divinity through dramatic, supernatural events during and after the crucifixion. Analyzes its historical role as an early, rejected source for the Passion narrative.','[{\"title\":\"Passion Narrative\",\"text\":\"Examine Gospel of Peter passion account\"},{\"title\":\"Supernatural Emphasis\",\"text\":\"Study dramatic divine revelation elements\"}]','[{\"question\":\"What is the Gospel of Peter?\",\"answer\":\"An early non-canonical gospel fragment focusing on Jesus\' passion and resurrection with unique supernatural elements and narrative details.\"},{\"question\":\"How does it differ from canonical passion accounts?\",\"answer\":\"It includes dramatic elements like a talking cross, giant resurrected figures, and more explicit supernatural manifestations during the crucifixion events.\"},{\"question\":\"Why was it rejected by the early church?\",\"answer\":\"Its docetic tendencies (emphasizing Jesus\' divinity over humanity) and theological differences from emerging orthodox accounts led to its exclusion.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(96,3,17,6,19,1,1,'The God of Hell and Heaven: Detailed Descriptions of Judgment','Focuses on God as meticulous judge with specific punishments and rewards','NTAPOC','NTAPOC 441','the-god-of-hell-and-heaven-detailed-descriptions-of-judgment','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Eschatological Studies\",\"value\":\"Explore early Christian afterlife concepts\"},{\"name\":\"Visual Tradition\",\"value\":\"Study origins of medieval hell and heaven imagery\"}]','2026-02-01','Focuses on the concept of God as the meticulous judge who administers specific, detailed punishments in Hell and rewards in Heaven. Examines the source of early Christian visual/apocalyptic tradition and its influence on later medieval thought.','[{\"title\":\"Judgment Scenes\",\"text\":\"Examine detailed afterlife punishment accounts\"},{\"title\":\"Medieval Influence\",\"text\":\"Study apocryphal impact on later theology\"}]','[{\"question\":\"What text is primarily studied in this course?\",\"answer\":\"The Apocalypse of Peter, which contains detailed, graphic descriptions of punishments in hell and rewards in heaven.\"},{\"question\":\"How did this influence later Christian thought?\",\"answer\":\"Its vivid descriptions directly influenced Dante\'s Divine Comedy and medieval artistic depictions of hell, purgatory, and heaven.\"},{\"question\":\"Why are these detailed descriptions theologically significant?\",\"answer\":\"They represent early attempts to systematize divine justice, correlating specific sins with specific punishments in the afterlife.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(97,14,2,7,19,1,1,'Seminar: Theories of Biblical Literature and Genre','Advanced study of narrative criticism, rhetoric, and literary theory applied to biblical anthology','BIBL','BIBL 501','seminar-theories-of-biblical-literature-and-genre','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Literary Theory\",\"value\":\"Master narrative criticism and rhetorical analysis of biblical texts\"},{\"name\":\"Genre Analysis\",\"value\":\"Develop skills in classifying and interpreting biblical literature forms\"}]','2026-02-01','An advanced study of narrative criticism, rhetoric, and literary theory as applied to the biblical anthology. Focuses on the politics of genre classification (e.g., epic as propaganda, apocalyptic as resistance literature) and reception history across diverse cultural settings.','[{\"title\":\"Genre Politics\",\"text\":\"Examine how genre classification serves ideological purposes\"},{\"title\":\"Reception History\",\"text\":\"Study diverse cultural interpretations of biblical texts\"}]','[{\"question\":\"What literary theories are applied in this course?\",\"answer\":\"Students apply narrative criticism, reader-response theory, rhetorical analysis, and post-structuralist approaches to biblical texts.\"},{\"question\":\"How is genre politically significant in biblical interpretation?\",\"answer\":\"Genre classification (e.g., calling something history vs. myth) significantly impacts how texts are authorized and what truths they are seen to convey.\"},{\"question\":\"What is reception history and why is it important?\",\"answer\":\"Reception history studies how texts have been interpreted across different cultures and periods, revealing the text\'s polysemic nature and cultural impact.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(98,14,2,7,19,1,1,'The Documentary Hypothesis: Post-JEDP Methodological Critique','Deep dive into historical-critical foundations of the Pentateuch beyond classical JEDP model','BIBL','BIBL 550','the-documentary-hypothesis-post-jedp-methodological-critique','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Source Criticism\",\"value\":\"Master advanced Pentateuchal source analysis techniques\"},{\"name\":\"Historical Methodology\",\"value\":\"Develop critical evaluation skills for biblical composition theories\"}]','2026-02-01','A deep dive into the historical-critical foundations of the Pentateuch, moving beyond the classical JEDP model. Focuses on post-source critical theories (Fragmentary Hypothesis, Supplementation Theory) and contemporary challenges to Pentateuchal authorship.','[{\"title\":\"Source Theory Evolution\",\"text\":\"Trace development from Wellhausen to contemporary models\"},{\"title\":\"Methodological Critique\",\"text\":\"Evaluate strengths and weaknesses of different approaches\"}]','[{\"question\":\"What is the Documentary Hypothesis?\",\"answer\":\"The theory that the Pentateuch was compiled from four main sources (J, E, D, P) over centuries, rather than being written by Moses.\"},{\"question\":\"What are post-source critical theories?\",\"answer\":\"Theories like the Fragmentary Hypothesis (many small sources) and Supplementation Theory (core text with later additions) that challenge or modify the classical JEDP model.\"},{\"question\":\"Why is Pentateuchal authorship controversial?\",\"answer\":\"Questions about Mosaic authorship involve issues of historical accuracy, theological authority, and the nature of biblical inspiration.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(99,14,2,7,19,1,1,'The Synoptic Problem: Q, M, L, and Theoretical Models','Advanced seminar on literary dependencies of the Gospels and theoretical models','BIBL','BIBL 660','The-Synoptic-Problem-Q-M-L-and-Theoretical-Models','386',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Gospel Studies\",\"value\":\"Master synoptic comparison and source analysis\"},{\"name\":\"Theoretical Modeling\",\"value\":\"Develop skills in constructing and testing gospel relationship models\"}]','2026-02-01','An advanced seminar on the literary dependencies of the Gospels. Focuses on specialized theories (Farrer, Griesbach) and the reconstruction of the hypothetical \"Q\" source to map the earliest strata of Jesus\'s sayings tradition.','[{\"title\":\"Source Reconstruction\",\"text\":\"Attempt to reconstruct Q and other hypothetical sources\"},{\"title\":\"Theoretical Comparison\",\"text\":\"Evaluate different synoptic problem solutions\"}]','[{\"question\":\"What is the Synoptic Problem?\",\"answer\":\"The question of the literary relationship between Matthew, Mark, and Luke, which share substantial material and structure (syn = seeing together).\"},{\"question\":\"What is the Q source?\",\"answer\":\"A hypothetical lost collection of Jesus\' sayings that Matthew and Luke allegedly drew from independently, explaining material they share but Mark lacks.\"},{\"question\":\"What alternative theories exist to the Two-Source hypothesis?\",\"answer\":\"The Farrer Hypothesis (Matthew used Mark, Luke used both) and the Griesbach Hypothesis (Matthew first, Luke used Matthew, Mark used both).\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 07:05:57'),
(100,14,3,7,19,1,1,'Advanced Canon Formation and Ideology','Graduate-level investigation into socio-political processes that defined biblical canon','HIST','HIST 510','advanced-canon-formation-and-ideology','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Canon Studies\",\"value\":\"Master historical processes of biblical canonization\"},{\"name\":\"Ideological Analysis\",\"value\":\"Develop critical understanding of theological power dynamics\"}]','2026-02-01','A graduate-level investigation into the socio-political and institutional processes that defined the biblical canon. Examines primary-source evidence (e.g., Marcion, Muratorian Fragment, Qumran) to analyze how theological power shaped textual exclusion and inclusion.','[{\"title\":\"Historical Evidence\",\"text\":\"Examine primary sources on canon formation\"},{\"title\":\"Power Dynamics\",\"text\":\"Analyze ideological forces in textual selection\"}]','[{\"question\":\"What factors influenced which books were included in the canon?\",\"answer\":\"Factors included apostolic authority, orthodoxy of content, widespread usage in churches, and suitability for liturgical reading.\"},{\"question\":\"Who was Marcion and why was he important for canon formation?\",\"answer\":\"Marcion\'s heretical canon (mid-2nd century) provoked orthodox churches to define their own authoritative scriptures more clearly.\"},{\"question\":\"What is the Muratorian Fragment?\",\"answer\":\"An early (c. 170 CE) list of New Testament books considered authoritative, showing early stages of canon formation.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(101,1,1,7,19,1,1,'Second Temple Judaism: Sectarianism and Textual Production','Advanced study of sectarian groups and Qumran library impact on text transmission','HIST','HIST 740','Second-Temple-Judaism-Sectarianism-and-Textual-Production-334306','375',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Sectarian Studies\",\"value\":\"Master analysis of Jewish sectarian movements\"},{\"name\":\"Textual Transmission\",\"value\":\"Develop skills in tracing manuscript traditions\"}]','2026-02-01','An advanced study of the sectarian groups of the Second Temple period (Pharisees, Sadducees, Essenes, Zealots). Focuses heavily on the Qumran library and its impact on the transmission, preservation, and interpretation of biblical and extra-biblical texts.','[{\"title\":\"Sectarian Groups\",\"text\":\"Compare Pharisees, Sadducees, Essenes, Zealots\"},{\"title\":\"Qumran Library\",\"text\":\"Study Dead Sea Scrolls and community life\"}]','[{\"question\":\"1. What is Second Temple Judaism?\",\"answer\":\"Second Temple Judaism refers to Jewish religious life and thought from 516 BCE, when the Second Temple in Jerusalem was completed, until its destruction in 70 CE by the Romans. This period shaped many beliefs, practices, and texts that later influenced Rabbinic Judaism and early Christianity.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 06:30:18'),
(102,14,4,7,19,1,1,'Material Culture and Textual Corroboration: Debates in the Levant','Seminar on archaeological methodology and its impact on historicity debate','ARCH','ARCH 520','material-culture-and-textual-corroboration-debates-in-the-levant','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Archaeological Method\",\"value\":\"Master advanced excavation and analysis techniques\"},{\"name\":\"Historiography\",\"value\":\"Develop critical evaluation of textual and material evidence\"}]','2026-02-01','A seminar on the latest archaeological methodology (radiocarbon dating, soil analysis) and its impact on the historicity debate. Students engage critically with the tension between the biblical narrative and the physical record from the Late Bronze Age to the Roman period.','[{\"title\":\"Scientific Methods\",\"text\":\"Study radiocarbon dating, stratigraphy, artifact analysis\"},{\"title\":\"Historiographic Tension\",\"text\":\"Examine biblical narrative vs. archaeological record\"}]','[{\"question\":\"What archaeological methods are emphasized?\",\"answer\":\"Radiocarbon dating, pottery typology, stratigraphic analysis, paleobotany, and settlement pattern analysis.\"},{\"question\":\"How does archaeology challenge biblical narratives?\",\"answer\":\"Some archaeological findings (e.g., Jericho walls, Exodus evidence, United Monarchy extent) don\'t align with biblical descriptions, raising historicity questions.\"},{\"question\":\"What is minimalist vs. maximalist debate?\",\"answer\":\"Minimalists skeptical of biblical historical claims vs. maximalists more accepting, with most scholars now in a centrist position evaluating each claim separately.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(103,14,5,7,19,1,1,'Philology, Semantics, and Translation Theory','Graduate-level course on linguistic evolution and translation philosophical problems','LING','LING 580','philology-semantics-and-translation-theory','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Philological Analysis\",\"value\":\"Master ancient language text analysis techniques\"},{\"name\":\"Translation Theory\",\"value\":\"Develop understanding of meaning transfer across languages\"}]','2026-02-01','A graduate-level course on the linguistic evolution of Ancient Hebrew, Aramaic, and Koine Greek. Focuses on the philosophical problem of untranslatability and how conceptual \"shifts\" in meaning affect key theological doctrines across different language editions.','[{\"title\":\"Linguistic Evolution\",\"text\":\"Trace Hebrew, Aramaic, Greek development\"},{\"title\":\"Translation Philosophy\",\"text\":\"Study untranslatability and meaning transfer\"}]','[{\"question\":\"What is philology and why is it important for biblical studies?\",\"answer\":\"Philology studies language in historical texts, crucial for understanding ancient biblical languages, textual variants, and authorial intent.\"},{\"question\":\"What are key examples of untranslatable concepts?\",\"answer\":\"Hebrew \"hesed\" (covenant loyalty/mercy), Greek \"logos\" (word/reason/principle), and \"dikaiosune\" (righteousness/justice) carry cultural/theological weight hard to translate fully.\"},{\"question\":\"How do translation choices affect theology?\",\"answer\":\"Choices like translating \"almah\" as virgin vs. young woman (Isaiah 7:14) or \"hilasterion\" as propitiation vs. expiation significantly shape Christian doctrine.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(104,14,46,7,19,1,1,'Meta-Hermeneutics: Logic and the Limits of Interpretation','Advanced seminar on interpretive philosophy from syllogistic logic to post-structuralism','LOGIC','LOGIC 601','Meta-Hermeneutics-Logic-and-the-Limits-of-Interpretation','395',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Hermeneutical Theory\",\"value\":\"Master interpretive philosophies and their applications\"},{\"name\":\"Logical Analysis\",\"value\":\"Develop skills in evaluating interpretive arguments\"}]','2026-02-01','An advanced seminar on interpretive philosophy, moving from formal syllogistic logic to post-structuralist and deconstructive approaches to biblical texts. Focuses on the role of reader-response theory, cultural lens, and intentionality in generating meaning.','[{\"title\":\"Interpretive Theories\",\"text\":\"Compare historical-critical, reader-response, deconstruction\"},{\"title\":\"Meaning Generation\",\"text\":\"Examine how readers and communities create meaning\"}]','[{\"question\":\"What is hermeneutics?\",\"answer\":\"The theory and methodology of interpretation, especially of biblical texts, examining how we derive meaning from written works.\"},{\"question\":\"How does reader-response theory change interpretation?\",\"answer\":\"It shifts focus from authorial intent to how readers actively construct meaning based on their context, experiences, and community.\"},{\"question\":\"What are the limits of interpretation?\",\"answer\":\"Limits include textual constraints, historical context, community traditions, and the need for coherent meaning while acknowledging interpretive plurality.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 07:49:12'),
(105,14,7,7,19,1,1,'Theological Cosmology and Scientific Revolutions','Comparative analysis of ancient and modern cosmologies and philosophical questions','SCI','SCI 610','Theological-Cosmology-and-Scientific-Revolutions','393',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Cosmological Comparison\",\"value\":\"Master analysis of ancient and modern universe models\"},{\"name\":\"Science-Religion Dialogue\",\"value\":\"Develop skills in interdisciplinary theological reflection\"}]','2026-02-01','A comparative analysis of ancient and modern cosmologies (Genesis/Babylonian models vs. Einstein/Quantum Theory). The course focuses on the philosophical question of God\'s role in a scientifically self-regulating universe (deism, process theology).','[{\"title\":\"Ancient Cosmologies\",\"text\":\"Study Genesis, Babylonian, Greek universe models\"},{\"title\":\"Modern Science\",\"text\":\"Examine relativity, quantum theory implications\"}]','[{\"question\":\"How do ancient Near Eastern cosmologies compare to Genesis?\",\"answer\":\"Genesis shares concepts like watery chaos and firmament with Babylonian texts but uniquely presents one God creating by sovereign word rather than divine conflict.\"},{\"question\":\"What theological models address modern science?\",\"answer\":\"Models include theistic evolution (God through natural processes), deism (God as initial creator), and process theology (God as persuader within process).\"},{\"question\":\"Can Genesis and modern cosmology be reconciled?\",\"answer\":\"Many theologians read Genesis as theological (who and why) not scientific (how and when), allowing compatibility with scientific cosmology.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 07:39:23'),
(106,14,8,7,19,1,1,'The Sociology of Ritual and Monotheistic Emergence','Study of anthropological theories behind religious transition and social control mechanisms','SOC','SOC 630','The-Sociology-of-Ritual-and-Monotheistic-Emergence','391',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Sociological Theory\",\"value\":\"Master application of social theory to religious phenomena\"},{\"name\":\"Ritual Analysis\",\"value\":\"Develop skills in interpreting religious practices sociologically\"}]','2026-02-01','A study of the anthropological and sociological theories behind religious transition (henotheism to monotheism). Focuses on the function of sacrifice, pilgrimage, and purity laws as mechanisms for social control, national identity, and boundary maintenance.','[{\"title\":\"Monotheistic Emergence\",\"text\":\"Study sociological factors in Israelite monotheism\"},{\"title\":\"Ritual Functions\",\"text\":\"Analyze sacrifice, purity, pilgrimage socially\"}]','[{\"question\":\"How do sociologists explain monotheism\'s emergence?\",\"answer\":\"Factors include political centralization under monarchy, need for national unity against enemies, prophetic critique of local shrines, and exile experience.\"},{\"question\":\"What social functions do rituals serve?\",\"answer\":\"Rituals create social cohesion, mark group boundaries, transmit values, manage anxiety, and legitimize social structures through sacred authority.\"},{\"question\":\"How do purity laws function as social control?\",\"answer\":\"They regulate behavior, mark insider/outsider status, maintain hierarchical order (priests/laity), and symbolize moral and social boundaries.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 07:29:27'),
(107,14,9,7,19,1,1,'Epistemology of Religious Claims: Fact, Myth, and Dogma','Intensive philosophical study of knowledge as it relates to biblical truth claims','PHIL','PHIL 680','Epistemology-of-Religious-Claims-Fact-Myth-and-Dogma','382',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Epistemological Analysis\",\"value\":\"Master philosophical evaluation of knowledge claims\"},{\"name\":\"Truth Theory\",\"value\":\"Develop understanding of different truth categories in religion\"}]','2026-02-01','An intensive philosophical study of knowledge (epistemology) as it relates to biblical \"truth.\" Examines the nature of historical evidence, the philosophical distinction between literary and historical truth, and the construction of religious dogma.','[{\"title\":\"Knowledge Theory\",\"text\":\"Study epistemology applied to religious claims\"},{\"title\":\"Truth Categories\",\"text\":\"Distinguish historical, literary, theological truth\"}]','[{\"question\":\"What is epistemology?\",\"answer\":\"The branch of philosophy studying the nature, sources, and limits of knowledge – how we know what we claim to know.\"},{\"question\":\"Can religious claims be empirically verified?\",\"answer\":\"Some aspects (historical events) can be investigated empirically, while transcendent claims (God\'s nature) rely on different forms of evidence and reasoning.\"},{\"question\":\"What is the difference between myth and falsehood?\",\"answer\":\"Myth conveys deep truth through symbolic narrative, not necessarily literal fact. Falsehood is intentional deception. Much biblical material may be mythic (in this technical sense) rather than strictly historical.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 07:01:32'),
(108,14,10,7,19,1,1,'The Historical Jesus: Criteria and Contested Claims','Doctoral-level review of the Third Quest for the Historical Jesus and authenticity criteria','CHRIS','CHRIS 701','The-Historical-Jesus-Criteria-and-Contested-Claims','381',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Historical Method\",\"value\":\"Master criteria for authentic Jesus tradition evaluation\"},{\"name\":\"Quest Scholarship\",\"value\":\"Develop comprehensive understanding of Historical Jesus research history\"}]','2026-02-01','A doctoral-level review of the \"Third Quest\" for the Historical Jesus. Focuses on the most difficult and controversial criteria (e.g., dissimilarity, embarrassment) and the scholarly consensus/disagreement on the authenticity of Jesus\'s deeds and sayings.','[{\"title\":\"Authenticity Criteria\",\"text\":\"Apply dissimilarity, embarrassment, multiple attestation\"},{\"title\":\"Quest History\",\"text\":\"Study First, Second, Third Quest developments\"}]','[{\"question\":\"What are the criteria of authenticity?\",\"answer\":\"Tools historians use to assess likely genuine Jesus material: dissimilarity (unlike Judaism & early church), embarrassment (awkward for early church), multiple attestation (in multiple sources), coherence (fits core message).\"},{\"question\":\"What is the Third Quest?\",\"answer\":\"Current phase (1980s-present) emphasizing Jesus within 1st-century Judaism, using Jewish sources, and focusing on his actions and context rather than just his sayings.\"},{\"question\":\"What is the scholarly consensus on Jesus?\",\"answer\":\"Jewish preacher from Galilee, baptized by John, taught about God\'s kingdom, performed healings/exorcisms, criticized temple authorities, crucified by Romans, followers believed he rose.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 06:59:04'),
(109,14,11,6,19,1,1,'Trinitarian and Christological Development','Deep dive into patristic and conciliar debates that defined Jesus\' identity','THEO','THEO 720','Trinitarian-and-Christological-Development','380',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Doctrinal History\",\"value\":\"Master development of Trinity and Christology concepts\"},{\"name\":\"Patristic Analysis\",\"value\":\"Develop skills in interpreting early church theological debates\"}]','2026-02-01','A deep dive into the patristic and conciliar debates that defined the identity of Jesus. Traces the logical and political evolution from early Jewish messianic claims to the Nicene and Chalcedonian definitions of the God-Man.','[{\"title\":\"Conciliar Debates\",\"text\":\"Study Nicaea, Constantinople, Chalcedon councils\"},{\"title\":\"Conceptual Evolution\",\"text\":\"Trace Logos, homoousios, hypostatic union development\"}]','[{\"question\":\"What does \\u201cTrinitarian development\\u201d mean?\",\"answer\":\"Trinitarian development refers to the historical and theological process by which early Christians articulated the belief that God is one essence in three persons\\u2014Father, Son, and Holy Spirit.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 06:53:48'),
(110,14,3,6,19,1,1,'Second Temple Judaism: Sectarianism and Textual Production','Advanced study of sectarian groups and textual transmission in the Second Temple period','HIST','HIST740','second-temple-judaism-sectarianism-and-textual-production','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Sectarian Insight\",\"value\":\"Understand the beliefs and practices of Pharisees, Sadducees, Essenes, and Zealots\"},{\"name\":\"Textual Expertise\",\"value\":\"Learn the impact of the Qumran library on biblical transmission and interpretation\"}]','2026-02-01','An advanced study of the sectarian groups of the Second Temple period (Pharisees, Sadducees, Essenes, Zealots). Focuses heavily on the Qumran library and its impact on the transmission, preservation, and interpretation of biblical and extra-biblical texts.','[{\"title\":\"Sectarian Analysis\",\"text\":\"Examine historical and theological distinctions among Second Temple groups\"},{\"title\":\"Textual Studies\",\"text\":\"Learn methodologies for analyzing Qumran and other Second Temple texts\"}]','[{\"question\":\"Who is eligible to enroll?\",\"answer\":\"Graduate students in Religious Studies or Biblical Studies with interest in Second Temple Judaism and textual criticism.\"},{\"question\":\"Are previous courses required?\",\"answer\":\"No, but prior knowledge of Hebrew Bible/Old Testament is beneficial.\"},{\"question\":\"How are students assessed?\",\"answer\":\"Through research papers and critical analyses of textual traditions.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
(111,14,2,6,19,1,1,'Pauline Epistles: Rhetorical Criticism and Post-Colonial Theory','Advanced study of Paul\'s letters using Greco-Roman rhetoric and contemporary theory','BIBL','BIBL760','Pauline-Epistles-Rhetorical-Criticism-and-Post-Colonial-Theory','374',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Rhetorical Mastery\",\"value\":\"Learn Greco-Roman rhetorical techniques (inventio, dispositio, elocutio) in Pauline letters\"},{\"name\":\"Critical Perspectives\",\"value\":\"Engage with Post-Colonial and socio-rhetorical readings\"}]','2026-02-01','A study of Paul\'s letters using advanced Greco-Roman rhetorical models (inventio, dispositio, elocutio). Focuses on contemporary scholarly approaches, including Post-Colonial and socio-rhetorical readings of his arguments on Law and Grace.','[{\"title\":\"Rhetorical Skills\",\"text\":\"Analyze argumentation techniques in Pauline texts\"},{\"title\":\"Critical Analysis\",\"text\":\"Evaluate contemporary theoretical frameworks applied to the epistles\"}]','[{\"question\":\"Who should take this course?\",\"answer\":\"Graduate students in Biblical Studies or Theology interested in Paul\'s letters and rhetorical criticism.\"},{\"question\":\"Do I need prior knowledge of Greek?\",\"answer\":\"Not strictly required, but familiarity with Biblical Greek is advantageous.\"},{\"question\":\"How is performance evaluated?\",\"answer\":\"Through essays analyzing rhetorical strategies and theoretical interpretations.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 06:22:03'),
(112,14,7,6,19,1,1,'Bioethics and Ancient Purity Systems','Philosophical seminar connecting ancient laws to modern bioethical debates','SCI','SCI780','Bioethics-and-Ancient-Purity-Systems','372',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Ethical Insight\",\"value\":\"Examine the relationship between ancient purity laws and modern bioethical issues\"},{\"name\":\"Comparative Analysis\",\"value\":\"Connect philosophical, legal, and medical perspectives from past to present\"}]','2026-02-01','A comparative, philosophical seminar connecting ancient purity laws, definitions of \"life,\" and medical practice with modern bioethics debates (genetic engineering, abortion, end-of-life care).','[{\"title\":\"Historical Ethics\",\"text\":\"Study ancient Jewish purity systems and their societal implications\"},{\"title\":\"Modern Application\",\"text\":\"Analyze ethical debates in genetics, reproductive rights, and end-of-life care\"}]','[{\"question\":\"Who can enroll?\",\"answer\":\"Graduate students interested in bioethics, religious law, and philosophy.\"},{\"question\":\"Is prior bioethics knowledge needed?\",\"answer\":\"No, but familiarity with philosophical or religious studies is useful.\"},{\"question\":\"Will there be discussion-based assessment?\",\"answer\":\"Yes, including case studies and philosophical essays.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 06:19:10'),
(113,14,9,6,19,1,1,'Metaphysics of Logos and Hellenistic Philosophy','Seminar bridging Greek philosophy and early Christian theology through Logos','PHIL','PHIL810','Metaphysics-of-Logos-and-Hellenistic-Philosophy','370',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Philosophical Depth\",\"value\":\"Understand Logos in Greek thought and Early Christian theology\"},{\"name\":\"Textual Analysis\",\"value\":\"Study Philo of Alexandria and the Gospel of John for philosophical integration\"}]','2026-02-01','A high-level seminar on the philosophical bridge between Greek thought (Stoicism, Platonism) and Early Christian theology through the concept of Logos (Divine Reason/Word). Focuses on the writings of Philo of Alexandria and the Gospel of John.','[{\"title\":\"Philosophical Study\",\"text\":\"Analyze Stoic and Platonic ideas in theological contexts\"},{\"title\":\"Textual Examination\",\"text\":\"Interpret primary texts bridging Greek philosophy and Christian theology\"}]','[{\"question\":\"Who is this course intended for?\",\"answer\":\"Graduate students in Theology or Philosophy interested in Hellenistic influences on early Christianity.\"},{\"question\":\"Is background in Greek philosophy required?\",\"answer\":\"Familiarity is helpful but not mandatory, key readings will be provided.\"},{\"question\":\"How will students be evaluated?\",\"answer\":\"Through textual analysis papers and seminar presentations.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 06:15:21'),
(114,14,2,6,19,1,1,'Textual Criticism: Manuscript Variants and Stemmatics','Methodological seminar on paleography and textual reconstruction','BIBL','BIBL830','Textual-Criticism-Manuscript-Variants-and-Stemmatics','368',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Textual Mastery\",\"value\":\"Learn to analyze manuscript families and reconstruct original texts\"},{\"name\":\"Critical Skills\",\"value\":\"Apply probability and stemmatic methods to resolve textual conflicts\"}]','2026-02-01','A methodological seminar on paleography and the science of textual reconstruction. Students learn advanced techniques for analyzing major manuscript families (Alexandrian, Byzantine, Western) and calculating the logical probability of original readings from conflicting witnesses.','[{\"title\":\"Paleography Skills\",\"text\":\"Study handwriting, scripts, and dating of manuscripts\"},{\"title\":\"Critical Reconstruction\",\"text\":\"Learn methods for resolving textual variants with logical probability\"}]','[{\"question\":\"Who is eligible?\",\"answer\":\"Graduate students specializing in textual criticism, Biblical studies, or manuscript research.\"},{\"question\":\"Are specific language skills needed?\",\"answer\":\"Yes, knowledge of Greek or Hebrew is highly recommended for text analysis.\"},{\"question\":\"How will students demonstrate competency?\",\"answer\":\"Through manuscript analysis exercises and critical essays.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 06:04:43'),
(115,14,11,6,19,1,1,'Advanced Theodicy and Post-Holocaust Interpretation','Analyzing the problem of evil in modern and post-Holocaust theological thought','THEO','THEO850','Advanced-Theodicy-and-Post-Holocaust-Interpretation','365',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Philosophical Insight\",\"value\":\"Engage critically with classic and modern approaches to theodicy\"},{\"name\":\"Historical Reflection\",\"value\":\"Examine post-Holocaust theological attempts to reconcile divine power and human suffering\"}]','2026-02-01','A critical, logical analysis of the problem of evil, moving beyond classic biblical models (Job). Focuses on modern philosophical and theological attempts to reconcile divine power with suffering, including process theology and post-Holocaust thought.','[{\"title\":\"Philosophical Analysis\",\"text\":\"Evaluate classical and contemporary models of theodicy\"},{\"title\":\"Historical Context\",\"text\":\"Study post-Holocaust interpretations and modern theological responses\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Graduate students in Theology, Religious Studies, or Philosophy interested in the problem of evil and modern theological approaches.\"},{\"question\":\"Is prior knowledge required?\",\"answer\":\"Familiarity with biblical texts and basic theological concepts is helpful but not mandatory.\"},{\"question\":\"How is assessment conducted?\",\"answer\":\"Through essays, critical analyses, and seminar presentations.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 05:54:42'),
(116,14,12,6,19,1,1,'Neuroscience, Cognitive Psychology, and Religious Experience','Scientific and philosophical examination of prophecy, revelation, and mystical cognition','RELI','RELI870','Neuroscience-Cognitive-Psychology-and-Religious-Experience','362',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Scientific Insight\",\"value\":\"Understand the neurological and cognitive basis of religious experiences\"},{\"name\":\"Analytical Skills\",\"value\":\"Study altered states of consciousness and prophetic claims critically\"}]','2026-02-01','A scientific and philosophical examination of \"Prophecy\" and \"Revelation.\" Focuses on the cognitive functions of religious experience, altered states of consciousness, and the neurological basis of mystical visions and prophetic claims.','[{\"title\":\"Cognitive Study\",\"text\":\"Analyze brain function, perception, and mystical experiences\"},{\"title\":\"Philosophical Perspective\",\"text\":\"Discuss implications for understanding religious cognition and prophecy\"}]','[{\"question\":\"Who is this course for?\",\"answer\":\"Graduate students in Religious Studies, Psychology of Religion, or Cognitive Science interested in mystical and prophetic phenomena.\"},{\"question\":\"Is scientific background required?\",\"answer\":\"A basic understanding of neuroscience or psychology is helpful but not mandatory.\"},{\"question\":\"How will students be assessed?\",\"answer\":\"Through research papers, critical discussions, and case study analyses.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 05:46:29'),
(117,14,13,6,19,1,1,'Master\'s Thesis Research Colloquium','Supervised research and seminar work for Master\'s thesis preparation','CAP','CAP899','Masters-Thesis-Research-Colloquium','357',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\":\"Research Skills\",\"value\":\"Develop methodology and analytical skills for graduate thesis work\"},{\"name\":\"Academic Guidance\",\"value\":\"Receive mentorship and feedback from faculty on research projects\"}]','2026-02-01','... (The description is cut off in the document)','[{\"title\":\"Thesis Preparation\",\"text\":\"Learn to structure and plan a research project for Master\'s level work\"},{\"title\":\"Seminar Engagement\",\"text\":\"Participate in discussions to refine research questions and methodology\"}]','[{\"question\":\"Who should enroll?\",\"answer\":\"Graduate students enrolled in the Master\'s program requiring thesis supervision.\"},{\"question\":\"Is this mandatory?\",\"answer\":\"Yes, it is required for successful completion of the Master\'s degree.\"},{\"question\":\"How is progress evaluated?\",\"answer\":\"Through regular meetings, seminar participation, and thesis milestones.\"}]','[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}]',NULL,NULL,NULL,NULL,59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 04:58:31'),
(118,14,18,6,19,1,2,'Introduction to the Gita','Introductory academic study of Religious Studies','Religious Studies','RSV 1010','introduction-to-the-gita','300',2,'D9b9h5mCgAc',1,3.00,NULL,100.00,'[{\"name\": \"Conceptual Understanding\", \"value\": \"Develop structured understanding of Religious Studies\"}, {\"name\": \"Critical Thinking\", \"value\": \"Improve analytical reading and interpretation skills\"}]','2026-02-01','An overview of the historical context, the Kurukshetra setting, and the primary dialogue between Krishna and Arjuna.','[{\"title\": \"Core Focus\", \"text\": \"Covers major texts, theories, and interpretations\"}, {\"title\": \"Academic Method\", \"text\": \"Applies historical, literary, and analytical methods\"}]','[{\"question\": \"Who should enroll?\", \"answer\": \"This course is suitable for students seeking academic grounding in the subject.\"}, {\"question\": \"Are there prerequisites?\", \"answer\": \"No formal prerequisites are required, but interest in the field is helpful.\"}, {\"question\": \"What will I gain?\", \"answer\": \"Students will gain analytical, interpretive, and academic discussion skills.\"}]','[{\"name\": \"To Be Announced\", \"professional_title\": \"Senior Lecturer in Biblical Studies\", \"photo\": \"301\"}]','','','','',59,1,1,NULL,'2026-01-15 00:30:00','2026-01-15 00:30:00'),
