INSERT INTO `degrees` VALUES
(1,'Philology of Ancient Texts','Philology-of-Ancient-Texts','475','<p>The <strong>LIN G180 – Philology of Ancient Texts</strong> is a comprehensive doctoral program designed for scholars devoted to the study of ancient languages, literary traditions, and historical texts. Students will gain expertise in textual criticism, manuscript preservation, and critical interpretation of Greek, Latin, and Sanskrit manuscripts.</p><p>The program includes:<br><br><br></p><ul><li><p><strong>Advanced Coursework:</strong> In-depth theoretical and practical training.</p></li><li><p><strong>Research Seminars:</strong> Interaction with international experts.</p></li><li><p><strong>Manuscript Workshops:</strong> Hands-on study of rare texts.</p></li><li><p><strong>Collaborative Projects:</strong> Opportunities for interdisciplinary research.</p></li></ul><p>Graduates are prepared for careers in academia, research institutions, libraries, museums, and cultural preservation organizations.</p><p>The doctoral program emphasizes:</p><ul><li><p><strong>Textual Criticism:</strong> Analyzing historical manuscript development.</p></li><li><p><strong>Philological Research:</strong> Comparative study of linguistic and literary texts.</p></li><li><p><strong>Scholarly Publication:</strong> Preparing research for peer-reviewed journals.<br><br></p></li></ul><hr><h3><br>Core Curriculum</h3><table><thead><tr><th>Semester</th><th>Course Title</th><th>Credits</th><th>Instructor</th><th>Mode</th></tr></thead><tbody><tr><td>1</td><td>Introduction to Ancient Texts</td><td>10</td><td>Prof. John Smith</td><td>Lecture</td></tr><tr><td>1</td><td>History of Philology</td><td>5</td><td>Dr. Emily Clarke</td><td>Seminar</td></tr><tr><td>2</td><td>Advanced Manuscript Studies</td><td>15</td><td>Dr. Michael Brown</td><td>Workshop</td></tr><tr><td>2</td><td>Textual Criticism Methods</td><td>10</td><td>Dr. Sarah Johnson</td><td>Lecture</td></tr><tr><td>3</td><td>Comparative Philology</td><td>10</td><td>Prof. Anna Lee</td><td>Seminar</td></tr><tr><td>3</td><td>Research Thesis Preparation</td><td>5</td><td>Prof. John Smith</td><td>Workshop</td></tr><tr><td>4</td><td>Dissertation &amp; Publication</td><td>20</td><td>Assigned Supervisor</td><td>Research</td></tr></tbody></table><hr><h3><br>Elective Modules<br><br></h3><table><thead><tr><th>Module Name</th><th>Description</th><th>Credits</th></tr></thead><tbody><tr><td>Bible Courses</td><td>In-depth study of biblical texts, interpretations, and historical context</td><td>5</td></tr><tr><td>Ancient Greek Literature</td><td>Analysis of Homeric epics, Greek poetry, and narrative traditions</td><td>5</td></tr><tr><td>Sanskrit Textual Studies</td><td>Critical examination of classical Sanskrit manuscripts and inscriptions</td><td>5</td></tr></tbody></table><hr><h3><br>Intake and Fee Schedule</h3><table><thead><tr><th>Intake Month</th><th>Duration (Months)</th><th>Tuition Fee (£)</th><th>Additional Costs (£)</th></tr></thead><tbody><tr><td>January 2026</td><td>60</td><td>4,000</td><td>500 (materials &amp; library access)</td></tr><tr><td>September 2026</td><td>60</td><td>4,000</td><td>500 (materials &amp; library access)</td></tr></tbody></table><p><em>Note: Students should have a strong background in at least one classical language (Greek, Latin, or Sanskrit).</em></p><hr><h3><br>Research Facilities</h3><p>Students have access to:</p><ul><li><p>Rare manuscript collections and archives.</p></li><li><p>Advanced libraries and digital research resources.</p></li><li><p>Interdisciplinary seminars on literature, linguistics, and historical studies.</p></li><li><p>International collaborations with research institutes.</p></li></ul><hr><h3><br>Program Learning Outcomes</h3><p>Graduates will be able to:</p><ul><li><p>Critically analyze ancient manuscripts and texts.</p></li><li><p>Interpret classical works with historical and linguistic accuracy.</p></li><li><p>Develop independent research projects and publish findings.</p></li><li><p>Contribute to academic and cultural preservation initiatives.</p></li><li><p>Present research at national and international conferences.</p></li></ul><hr><h3><br>Sample Weekly Schedule</h3><table><thead><tr><th>Day</th><th>Activity</th><th>Location</th><th>Hours</th></tr></thead><tbody><tr><td>Monday</td><td>Lecture: Introduction to Texts</td><td>Lecture Hall A</td><td>3</td></tr><tr><td>Tuesday</td><td>Workshop: Manuscript Handling</td><td>Library – Rare Manuscripts</td><td>4</td></tr><tr><td>Wednesday</td><td>Seminar: Textual Criticism</td><td>Seminar Room 2</td><td>2</td></tr><tr><td>Thursday</td><td>Research Lab: Comparative Studies</td><td>Research Lab 1</td><td>4</td></tr><tr><td>Friday</td><td>Individual Research / Meetings</td><td>Supervisor’s Office</td><td>3</td></tr></tbody></table><hr><h3><br>Assessment and Dissertation</h3><ul><li><p><strong>Continuous Assessment:</strong> Essays, presentations, and research projects for each module.</p></li><li><p><strong>Dissertation:</strong> Submission of original research at program completion.</p></li><li><p><strong>Oral Defense:</strong> Dissertation defense before a panel of experts.</p></li></ul><hr><h3><br>Why Study Philology of Ancient Texts?</h3><ul><li><p>Access to <strong>world-class manuscript archives</strong> and research libraries.</p></li><li><p>Engage in <strong>interdisciplinary and international research collaborations</strong>.</p></li><li><p>Gain skills in <strong>critical textual analysis</strong>, <strong>historical linguistics</strong>, and <strong>scholarly publication</strong>.</p></li><li><p>Career opportunities in <strong>academia, research, libraries, and cultural institutions</strong>.</p></li></ul>',19,7,1,1,'2026-01-31','60','Advanced Philology Program','85',4297,1,NULL,'2026-01-19 04:13:56','2026-01-19 05:27:31'),
(2,'Biblical Studies and Manuscript Research','Biblical-Studies-and-Manuscript-Research','476','<p>The <strong>Doctoral Program in Biblical Studies and Manuscript Research</strong> is designed for scholars aiming to specialize in the historical, linguistic, and literary study of biblical texts. This program blends rigorous academic research with hands-on manuscript analysis to prepare graduates for careers in academia, archives, and research institutes.</p><p>The program includes:</p><ul><li><p><strong>Advanced Coursework:</strong> Focused study of biblical languages, history, and interpretations.</p></li><li><p><strong>Seminars &amp; Workshops:</strong> In collaboration with international research centers.</p></li><li><p><strong>Manuscript Handling:</strong> Study of rare manuscripts, ancient codices, and inscriptions.</p></li><li><p><strong>Research Collaborations:</strong> Interdisciplinary projects with linguistics, history, and theology departments.</p></li></ul><p>Program emphases:</p><ul><li><p><strong>Textual Criticism:</strong> Critical analysis of biblical manuscripts and historical documents.</p></li><li><p><strong>Historical Research:</strong> Tracing development of texts, translations, and interpretations.</p></li><li><p><strong>Publication &amp; Dissemination:</strong> Preparing research for journals, conferences, and academic forums.</p></li></ul><hr><h3>Core Curriculum</h3><table><thead><tr><th>Semester</th><th>Course Title</th><th>Credits</th><th>Instructor</th><th>Mode</th></tr></thead><tbody><tr><td>1</td><td>Introduction to Biblical Studies</td><td>10</td><td>Prof. Mary Thompson</td><td>Lecture</td></tr><tr><td>1</td><td>History of Early Religious Texts</td><td>5</td><td>Dr. James Harrison</td><td>Seminar</td></tr><tr><td>2</td><td>Manuscript Preservation Techniques</td><td>15</td><td>Dr. Rebecca Lewis</td><td>Workshop</td></tr><tr><td>2</td><td>Biblical Languages: Greek &amp; Hebrew</td><td>10</td><td>Dr. Samuel White</td><td>Lecture</td></tr><tr><td>3</td><td>Comparative Religious Texts</td><td>10</td><td>Prof. Elizabeth King</td><td>Seminar</td></tr><tr><td>3</td><td>Research Thesis Preparation</td><td>5</td><td>Prof. Mary Thompson</td><td>Workshop</td></tr><tr><td>4</td><td>Dissertation &amp; Scholarly Publication</td><td>20</td><td>Assigned Supervisor</td><td>Research</td></tr></tbody></table><hr><h3>Elective Modules</h3><table><thead><tr><th>Module Name</th><th>Description</th><th>Credits</th></tr></thead><tbody><tr><td>Old Testament Studies</td><td>Analysis of historical, linguistic, and literary aspects</td><td>5</td></tr><tr><td>New Testament Exegesis</td><td>Critical interpretation and study of textual traditions</td><td>5</td></tr><tr><td>Ancient Hebrew &amp; Greek Texts</td><td>Understanding original texts in historical languages</td><td>5</td></tr><tr><td>Biblical Archaeology</td><td>Archaeological context of scriptural manuscripts and artifacts</td><td>5</td></tr></tbody></table><hr><h3>Intake and Fee Schedule</h3><table><thead><tr><th>Intake Month</th><th>Duration (Months)</th><th>Tuition Fee (£)</th><th>Additional Costs (£)</th></tr></thead><tbody><tr><td>January 2026</td><td>60</td><td>4,200</td><td>500 (materials &amp; library access)</td></tr><tr><td>September 2026</td><td>60</td><td>4,200</td><td>500 (materials &amp; library access)</td></tr></tbody></table><p><em>Note: Strong foundation in ancient languages or prior theological studies recommended.</em></p><hr><h3>Research Facilities</h3><p>Students gain access to:</p><ul><li><p>Rare biblical manuscript collections and archives.</p></li><li><p>Digital libraries for historical and linguistic research.</p></li><li><p>Seminars with visiting scholars in theology, history, and philology.</p></li><li><p>Partnerships with international theological and historical institutes.</p></li></ul><hr><h3>Program Learning Outcomes</h3><p>Graduates will be able to:</p><ul><li><p>Critically analyze biblical manuscripts and historical texts.</p></li><li><p>Interpret ancient religious documents accurately within historical context.</p></li><li><p>Conduct independent research and produce scholarly publications.</p></li><li><p>Collaborate on interdisciplinary projects in history, linguistics, and theology.</p></li><li><p>Present research findings at conferences worldwide.</p></li></ul><hr><h3>Sample Weekly Schedule</h3><table><thead><tr><th>Day</th><th>Activity</th><th>Location</th><th>Hours</th></tr></thead><tbody><tr><td>Monday</td><td>Lecture: Introduction to Biblical Studies</td><td>Lecture Hall B</td><td>3</td></tr><tr><td>Tuesday</td><td>Workshop: Manuscript Handling</td><td>Library – Rare Manuscripts</td><td>4</td></tr><tr><td>Wednesday</td><td>Seminar: Historical Contexts</td><td>Seminar Room 3</td><td>2</td></tr><tr><td>Thursday</td><td>Research Lab: Textual Analysis</td><td>Research Lab 2</td><td>4</td></tr><tr><td>Friday</td><td>Individual Research / Meetings</td><td>Supervisor’s Office</td><td>3</td></tr></tbody></table><hr><h3>Assessment and Dissertation</h3><ul><li><p><strong>Continuous Assessment:</strong> Essays, presentations, and research projects for each module.</p></li><li><p><strong>Dissertation:</strong> Submission of original research at program completion.</p></li><li><p><strong>Oral Defense:</strong> Defense of dissertation before an expert panel.</p></li></ul><hr><h3>Why Study Biblical Studies and Manuscript Research?</h3><ul><li><p>Access to rare biblical manuscripts and archival collections.</p></li><li><p>Gain expertise in textual analysis, historical linguistics, and manuscript preservation.</p></li><li><p>Career opportunities in academic institutions, libraries, and international research centers.</p></li><li><p>Opportunities for interdisciplinary research and global collaborations.</p></li></ul>',19,7,1,1,'2026-01-31','60','Advanced Biblical Studies Program','88',4200,1,NULL,'2026-01-19 06:44:30','2026-01-19 06:44:30'),
(3,'Master of Biblical Exegesis and Ancient Languages','Master-of-Biblical-Exegesis-and-Ancient-Languages','477','<p>The <strong>Master’s in Biblical Exegesis and Ancient Languages</strong> equips students with advanced skills to interpret, analyze, and translate biblical and historical texts. Students engage with Greek, Latin, and Hebrew manuscripts, learning both theoretical and practical aspects of scriptural scholarship.</p><p>The program includes:</p><ul><li><p><strong>Textual Analysis:</strong> Study of biblical passages and historical manuscripts.</p></li><li><p><strong>Language Proficiency:</strong> Advanced training in ancient languages.</p></li><li><p><strong>Research Seminars:</strong> Collaboration with experts in theology, linguistics, and history.</p></li><li><p><strong>Field Studies:</strong> Visits to archives, libraries, and research centers.</p></li></ul><p>Program emphases:</p><ul><li><p><strong>Exegesis:</strong> Critical interpretation of biblical texts.</p></li><li><p><strong>Manuscript Study:</strong> Hands-on examination of ancient codices and scrolls.</p></li><li><p><strong>Publication Skills:</strong> Prepare research for journals and academic presentations.</p></li></ul><hr><h3>Core Curriculum</h3><table><thead><tr><th>Semester</th><th>Course Title</th><th>Credits</th><th>Instructor</th><th>Mode</th></tr></thead><tbody><tr><td>1</td><td>Advanced Greek &amp; Hebrew Texts</td><td>10</td><td>Prof. David Roberts</td><td>Lecture</td></tr><tr><td>1</td><td>Biblical Hermeneutics</td><td>5</td><td>Dr. Rachel Green</td><td>Seminar</td></tr><tr><td>2</td><td>Historical Context of Scriptures</td><td>10</td><td>Dr. Mark Hamilton</td><td>Lecture</td></tr><tr><td>2</td><td>Manuscript Analysis Workshop</td><td>10</td><td>Dr. Clara Wilson</td><td>Workshop</td></tr><tr><td>3</td><td>Comparative Religious Studies</td><td>10</td><td>Prof. Linda Foster</td><td>Seminar</td></tr><tr><td>3</td><td>Research Thesis Preparation</td><td>5</td><td>Prof. David Roberts</td><td>Workshop</td></tr><tr><td>4</td><td>Dissertation &amp; Publication</td><td>15</td><td>Assigned Supervisor</td><td>Research</td></tr></tbody></table><hr><h3>Elective Modules</h3><table><thead><tr><th>Module Name</th><th>Description</th><th>Credits</th></tr></thead><tbody><tr><td>Biblical Texts in Greek</td><td>Study of New Testament manuscripts in Koine Greek</td><td>5</td></tr><tr><td>Latin Scriptural Traditions</td><td>Analysis of Latin Vulgate and other medieval translations</td><td>5</td></tr><tr><td>Hebrew Bible Studies</td><td>Advanced interpretation of Hebrew scriptures</td><td>5</td></tr><tr><td>Archaeology of Early Christianity</td><td>Examination of archaeological sites and artifacts related to early Christianity</td><td>5</td></tr></tbody></table><hr><h3>Intake and Fee Schedule</h3><table><thead><tr><th>Intake Month</th><th>Duration (Months)</th><th>Tuition Fee (£)</th><th>Additional Costs (£)</th></tr></thead><tbody><tr><td>January 2026</td><td>24</td><td>2,800</td><td>300 (materials &amp; library access)</td></tr><tr><td>September 2026</td><td>24</td><td>2,800</td><td>300 (materials &amp; library access)</td></tr></tbody></table><p><em>Note: Applicants must have an undergraduate degree in Theology, History, or Languages.</em></p><hr><h3>Research Facilities</h3><p>Students gain access to:</p><ul><li><p>Rare biblical manuscripts and ancient texts.</p></li><li><p>Libraries with extensive historical archives.</p></li><li><p>Digital research resources for textual and linguistic studies.</p></li><li><p>Seminars and workshops with visiting scholars.</p></li></ul><hr><h3>Program Learning Outcomes</h3><p>Graduates will be able to:</p><ul><li><p>Analyze and interpret biblical and historical manuscripts.</p></li><li><p>Conduct independent research in exegesis and ancient languages.</p></li><li><p>Prepare scholarly publications and conference presentations.</p></li><li><p>Collaborate on interdisciplinary projects in historical and religious studies.</p></li></ul><hr><h3>Sample Weekly Schedule</h3><table><thead><tr><th>Day</th><th>Activity</th><th>Location</th><th>Hours</th></tr></thead><tbody><tr><td>Monday</td><td>Lecture: Biblical Texts in Greek</td><td>Lecture Hall C</td><td>3</td></tr><tr><td>Tuesday</td><td>Workshop: Manuscript Study</td><td>Library – Special Collections</td><td>4</td></tr><tr><td>Wednesday</td><td>Seminar: Historical Contexts</td><td>Seminar Room 4</td><td>2</td></tr><tr><td>Thursday</td><td>Research Lab: Textual Analysis</td><td>Research Lab 3</td><td>4</td></tr><tr><td>Friday</td><td>Individual Research / Meetings</td><td>Supervisor’s Office</td><td>3</td></tr></tbody></table><hr><h3>Assessment and Dissertation</h3><ul><li><p><strong>Continuous Assessment:</strong> Essays, presentations, and coursework for each module.</p></li><li><p><strong>Dissertation:</strong> Completion of original research in biblical exegesis.</p></li><li><p><strong>Oral Defense:</strong> Defense of dissertation before a faculty panel.</p></li></ul><hr><h3>Why Study Master’s in Biblical Exegesis and Ancient Languages?</h3><ul><li><p>Deepen expertise in biblical texts and ancient languages.</p></li><li><p>Hands-on experience with manuscripts and historical texts.</p></li><li><p>Career opportunities in research, archives, religious institutions, and academic teaching.</p></li><li><p>Opportunities for international collaboration and publications.</p></li></ul>',19,8,1,2,'2026-01-31','24','Biblical Language Proficiency Program','80',2800,1,NULL,'2026-01-19 06:47:18','2026-01-19 06:47:18'),
(4,'Bachelor of Historical Arts & Cultural Studies','Bachelor-of-Historical-Arts-Cultural-Studies','478','<p>The <strong>Bachelor’s in Historical Arts &amp; Cultural Studies</strong> provides students with an immersive study of ancient art, architecture, and cultural traditions. The program emphasizes critical analysis, historical research, and preservation of cultural heritage.</p><p>Students will explore topics such as classical art forms, museum studies, historical architecture, and cultural anthropology.</p><p>Program highlights:</p><ul><li><p><strong>Foundational Coursework:</strong> Study of art history, ancient civilizations, and cultural practices.</p></li><li><p><strong>Practical Workshops:</strong> Hands-on training in preservation techniques and archival research.</p></li><li><p><strong>Field Studies:</strong> Visits to historical sites, museums, and galleries.</p></li><li><p><strong>Research Projects:</strong> Conduct independent studies on cultural artifacts or historical art pieces.</p></li></ul><p>Program emphases:</p><ul><li><p><strong>Art &amp; Culture Analysis:</strong> Understanding the development of artistic movements and styles.</p></li><li><p><strong>Cultural Preservation:</strong> Methods to conserve and interpret historical artifacts.</p></li><li><p><strong>Research &amp; Documentation:</strong> Skills for academic writing and publication in cultural studies.</p></li></ul><hr><h3>Core Curriculum</h3><table><thead><tr><th>Semester</th><th>Course Title</th><th>Credits</th><th>Instructor</th><th>Mode</th></tr></thead><tbody><tr><td>1</td><td>Introduction to Ancient Art &amp; Culture</td><td>10</td><td>Prof. Emily Clarke</td><td>Lecture</td></tr><tr><td>1</td><td>History of Civilizations</td><td>5</td><td>Dr. Michael Brown</td><td>Lecture</td></tr><tr><td>2</td><td>Classical Art Techniques</td><td>10</td><td>Prof. Anna Lee</td><td>Workshop</td></tr><tr><td>2</td><td>Museum Studies &amp; Curation</td><td>5</td><td>Dr. John Smith</td><td>Seminar</td></tr><tr><td>3</td><td>Architectural History</td><td>10</td><td>Prof. Sarah Johnson</td><td>Lecture</td></tr><tr><td>3</td><td>Cultural Anthropology</td><td>5</td><td>Dr. David Roberts</td><td>Seminar</td></tr><tr><td>4</td><td>Research Project: Historical Art</td><td>10</td><td>Assigned Supervisor</td><td>Research</td></tr><tr><td>4</td><td>Capstone Exhibition</td><td>10</td><td>Prof. Emily Clarke</td><td>Project</td></tr></tbody></table><hr><h3>Elective Modules</h3><table><thead><tr><th>Module Name</th><th>Description</th><th>Credits</th></tr></thead><tbody><tr><td>Ancient Sculpture</td><td>Study of Greek, Roman, and Egyptian sculptures</td><td>5</td></tr><tr><td>Historical Architecture</td><td>Examination of significant architectural periods and styles</td><td>5</td></tr><tr><td>Art Conservation Techniques</td><td>Practical preservation methods for paintings and artifacts</td><td>5</td></tr><tr><td>Cultural Anthropology</td><td>Understanding societies and cultural heritage globally</td><td>5</td></tr><tr><td>Museum Curation</td><td>Principles of managing museum collections and exhibitions</td><td>5</td></tr></tbody></table><hr><h3>Intake and Fee Schedule</h3><table><thead><tr><th>Intake Month</th><th>Duration (Months)</th><th>Tuition Fee (£)</th><th>Additional Costs (£)</th></tr></thead><tbody><tr><td>January 2026</td><td>36</td><td>1,900 per year</td><td>250 (materials &amp; workshops)</td></tr><tr><td>September 2026</td><td>36</td><td>1,900 per year</td><td>250 (materials &amp; workshops)</td></tr></tbody></table><p><em>Note: Applicants should have completed secondary education with a focus on history, art, or cultural studies.</em></p><hr><h3>Research &amp; Facilities</h3><p>Students gain access to:</p><ul><li><p>Museums and art archives with ancient and classical collections.</p></li><li><p>Libraries and digital databases of historical artifacts.</p></li><li><p>Workshops on preservation and restoration techniques.</p></li><li><p>Field trips to heritage sites, galleries, and international cultural institutions.</p></li></ul><hr><h3>Program Learning Outcomes</h3><p>Graduates will be able to:</p><ul><li><p>Analyze historical and cultural art with contextual accuracy.</p></li><li><p>Document and preserve cultural artifacts and historical works.</p></li><li><p>Conduct independent research projects and publish findings.</p></li><li><p>Contribute to museums, galleries, and cultural preservation initiatives.</p></li><li><p>Present research in exhibitions, seminars, and conferences.</p></li></ul><hr><h3>Sample Weekly Schedule</h3><table><thead><tr><th>Day</th><th>Activity</th><th>Location</th><th>Hours</th></tr></thead><tbody><tr><td>Monday</td><td>Lecture: Introduction to Ancient Art</td><td>Lecture Hall B</td><td>3</td></tr><tr><td>Tuesday</td><td>Workshop: Artifact Handling</td><td>Art Lab / Archives</td><td>4</td></tr><tr><td>Wednesday</td><td>Seminar: Cultural History</td><td>Seminar Room 2</td><td>2</td></tr><tr><td>Thursday</td><td>Research Lab: Art Documentation</td><td>Research Lab 1</td><td>3</td></tr><tr><td>Friday</td><td>Field Study: Museum Visit / Archives</td><td>Museum / Library</td><td>3</td></tr></tbody></table><hr><h3>Assessment &amp; Capstone Project</h3><ul><li><p><strong>Continuous Assessment:</strong> Essays, research projects, and practical workshops.</p></li><li><p><strong>Capstone Exhibition:</strong> Presentation of a curated project based on historical or cultural research.</p></li><li><p><strong>Final Presentation:</strong> Exhibition and defense of work to faculty and peers.</p></li></ul><hr><h3>Why Study Historical Arts &amp; Cultural Studies?</h3><ul><li><p>Gain expertise in the analysis, documentation, and preservation of ancient arts.</p></li><li><p>Engage with historical and cultural heritage through fieldwork and research.</p></li><li><p>Prepare for careers in museums, galleries, research, education, and cultural institutions.</p></li><li><p>Strong foundation for further studies at the Master’s or Doctoral level.</p></li></ul>',19,7,1,1,'2026-01-31','75','High School Diploma with Arts or History Focus','75',1900,1,NULL,'2026-01-19 06:50:47','2026-01-19 06:50:47');
