INSERT INTO `email_templates` VALUES
(1,'User Create','user-create','User Create','\r\n                    Hello, {{name}}\r\n\r\n                    Thank you for creating an account with us. Please verify your email address to activate your account by clicking the link below:\r\n\r\n                    Verification Link: {{link}}\r\n\r\n                    Your account details:\r\n                    Email: {{email}}\r\n                    Temporary Password: {{password}}\r\n\r\n                    If you did not register with us, please ignore this email.\r\n\r\n                    Best regards.\r\n                ',1,'{{name}}, {{email}}, {{link}}, {{password}}',5,NULL,'2024-12-02 18:39:37','2024-12-02 18:39:37'),
(2,'Password Reset','password-reset','Password Reset','\r\n                    Hello, {{name}}\r\n\r\n                    We received a request to reset the password associated with your account ({{email}}). Please click the link below to reset your password:\r\n\r\n                    Reset Password Link: {{link}}\r\n\r\n                    If you did not make this request, please contact our support team immediately.\r\n\r\n                    Best regards.\r\n                ',1,'{{name}}, {{email}}, {{link}}',5,NULL,'2024-12-02 18:39:37','2024-12-02 18:39:37'),
(3,'Verify','verify','Verify','\r\n                     Hello, {{name}}\r\n\r\n                    To complete the registration process, please verify your email address by clicking the link below:\r\n\r\n                    Verification Link: {{link}}\r\n\r\n                    If you did not sign up for this account using {{email}}, please disregard this message.\r\n\r\n                    Best regards.\r\n                ',1,'{{name}}, {{email}}, {{link}}',5,NULL,'2024-12-02 18:39:37','2024-12-02 18:39:37'),
(4,'Consultation Booking Success','consultation-booking-success','Consultation Booking Success','\r\n                    Hello, {{name}}\r\n\r\n                    Your consultation has been successfully booked! Here are the details:\r\n\r\n                    Email: {{email}}\r\n                    Consultation Details: {{link}}\r\n\r\n                    If you have any questions or need to reschedule, feel free to reach out.\r\n\r\n                    Best regards.\r\n                ',1,'{{name}}, {{email}}, {{link}}',4,NULL,'2024-12-02 18:39:37','2024-12-02 18:39:37'),
(5,'Consultation Booking Consultant Notification','consultation-booking-consultant-notification','Consultation Booking Consultant Notification','\r\n                    Hello, {{name}}\r\n\r\n                    You have received a new consultation booking request from {{student_name}}. Please check the details below and confirm at your earliest convenience:\r\n\r\n                    Booking Details: {{link}}\r\n\r\n                    Thank you for providing your valuable expertise.\r\n\r\n                    Best regards.\r\n                ',1,'{{name}}, {{student_name}}, {{link}}',4,NULL,'2024-12-02 18:39:37','2024-12-02 18:39:37'),
(6,'Consultation Meeting Link','consultation-meeting-link','Consultation Meeting Link','\r\n                    Hello, {{name}}\r\n\r\n                    Your consultation meeting has been scheduled. Use the link below to join the meeting at the designated time:\r\n\r\n                    Meeting Link: {{link}}\r\n\r\n                    If you have any questions, feel free to contact our support team.\r\n\r\n                    Best regards.\r\n\r\n                ',1,'{{name}}, {{link}}',4,NULL,'2024-12-02 18:39:37','2024-12-02 18:39:37'),
(7,'Event Booking Confirmation','event-booking-confirmation','Event Booking Confirmation','\r\n                    Hello, {{name}}\r\n\r\n                    Your booking for the event has been confirmed! Here are your booking details:\r\n\r\n                    Email: {{email}}\r\n                    Event Details: {{link}}\r\n\r\n                    We look forward to seeing you at the event!\r\n\r\n                    Best regards.\r\n                ',1,'{{name}}, {{email}}, {{link}}',2,NULL,'2024-12-02 18:39:37','2024-12-02 18:39:37'),
(8,'Course Purchase Success','course-purchase-success','Course Purchase Success','\r\n                    Hello, {{name}}\r\n\r\n                    Congratulations on your course purchase! You can access the course materials using the link below:\r\n\r\n                    Course Access Link: {{link}}\r\n\r\n                    Registered Email: {{email}}\r\n\r\n                    If you encounter any issues, feel free to contact us.\r\n\r\n                    Best regards.\r\n\r\n                ',1,'{{name}}, {{email}}, {{link}}',2,NULL,'2024-12-02 18:39:37','2024-12-02 18:39:37'),
(9,'Invoice Payment Success','invoice-payment-success','Invoice Payment Success','\r\n                    Hello, {{name}}\r\n\r\n                    Thank you for payment our invoice. Here are your details:\r\n\r\n                    Email: {{email}}\r\n                    Link: {{link}}\r\n\r\n                    If you have any questions or need assistance, please contact our support team.\r\n\r\n                    Best regards.\r\n                ',1,'{{name}}, {{email}}, {{link}}',2,NULL,'2024-12-02 18:39:37','2024-12-02 18:39:37'),
(10,'Service Order Status Change','service-order-status-change','Service Order Status Change','\r\n                    Hello, {{name}}\r\n\r\n                    Change your service order status. Here are your details:\r\n\r\n                    Email: {{email}}\r\n                    Link: {{link}}\r\n\r\n                    If you have any questions or need assistance, please contact our support team.\r\n\r\n                    Best regards.\r\n                ',1,'{{name}}, {{email}}, {{link}}',2,NULL,'2024-12-02 18:39:37','2024-12-02 18:39:37'),
(11,'Onboard Request','onboard-request','Onboard Request','\r\n                    Hello, {{name}}\r\n\r\n                    Here are your onboard request details:\r\n\r\n                    Email: {{email}}\r\n                    Link: {{link}}\r\n\r\n                    If you have any questions or need assistance, please contact our support team.\r\n\r\n                    Best regards.\r\n                ',1,'{{name}}, {{email}}, {{link}}',2,NULL,'2024-12-02 18:39:37','2024-12-02 18:39:37'),
(12,'Order Task Status Change','order-task-status-change','Order Task Status Change','\r\n                    Hello, {{name}}\r\n\r\n                    Here are your order task status change details:\r\n\r\n                    Email: {{email}}\r\n                    Link: {{link}}\r\n\r\n                    If you have any questions or need assistance, please contact our support team.\r\n\r\n                    Best regards.\r\n                ',1,'{{name}}, {{email}}, {{link}}',2,NULL,'2024-12-02 18:39:37','2024-12-02 18:39:37'),
(13,'Consultation Booking Status Update','consultation-booking-status-update','Consultation Booking Status Update','\r\n                    Hello, {{name}}\r\n\r\n                    Here are your consultation booking status update details:\r\n\r\n                    Email: {{email}}\r\n                    Status: {{status}}\r\n\r\n                    If you have any questions or need assistance, please contact our support team.\r\n\r\n                    Best regards.\r\n                ',1,'{{name}}, {{email}}, {{status}}',2,NULL,'2024-12-02 18:39:37','2024-12-02 18:39:37'),
(14,'Service Purchase Success','service-purchase-success','Service Purchase Success','\r\n                    Hello, {{name}}\r\n\r\n                    Here are your Service Purchase Success details:\r\n\r\n                    Email: {{email}}\r\n                    Link: {{link}}\r\n\r\n                    If you have any questions or need assistance, please contact our support team.\r\n\r\n                    Best regards.\r\n                ',1,'{{name}}, {{email}}, {{link}}',2,NULL,'2024-12-02 18:39:37','2024-12-02 18:39:37'),
(15,'Onboard Done By Student','onboard-done-by-student','Onboard Done By Student','\r\n                    Hello, {{name}}\r\n\r\n                    Here are your onboard done Success details:\r\n\r\n                    Email: {{email}}\r\n                    Link: {{link}}\r\n\r\n                    If you have any questions or need assistance, please contact our support team.\r\n\r\n                    Best regards.\r\n                ',1,'{{name}}, {{email}}, {{link}}',2,NULL,'2024-12-02 18:39:37','2024-12-02 18:39:37');
