INSERT INTO `events` VALUES
(23,'Understanding Divine Names in Biblical Literature',2,'Understanding-Divine-Names-in-Biblical-Literature','2026-01-19 10:10:00',NULL,NULL,'<p>This workshop introduces learners to the historical and linguistic development of divine names in biblical texts. Participants will explore how names evolved across different periods and cultures, with references to Hebrew and early Christian traditions. The session is designed to support academic curiosity and foundational research skills.</p>',0.00,'[\"1\"]','[\"19\"]','[\"1\",\"2\",\"3\"]','293',1,NULL,'2026-01-12 05:13:27','2026-01-12 05:13:27'),
(24,'Language, Power, and Identity in Ancient Religious Texts',2,'Language-Power-and-Identity-in-Ancient-Religious-Texts','2026-01-19 10:00:00',NULL,NULL,'<p>This lecture series examines how language and naming practices shaped religious authority and community identity in ancient societies. Drawing from biblical, historical, and sociological sources, the session offers insights relevant to advanced students and researchers in theology and religious studies.</p>',0.00,'[\"1\"]','[\"19\"]','[\"2\",\"3\"]','294',1,NULL,'2026-01-12 05:14:58','2026-01-12 05:14:58'),
(25,'Malayalam Language Workshop',2,'Malayalam-Language-Workshop','2026-01-19 10:10:00',NULL,NULL,'<p>A hands-on workshop designed for beginners and enthusiasts to learn the basics of Malayalam language, script, and pronunciation. Participants will engage in interactive exercises and cultural discussions to connect with Kerala’s heritage.</p>',0.00,'[\"1\"]','[\"19\"]','[\"1\",\"2\",\"3\"]','297',1,NULL,'2026-01-12 05:22:24','2026-01-12 05:22:24');
/*!40000 ALTER TABLE `events` ENABLE KEYS */;
UNLOCK TABLES;

