INSERT INTO `faqs` VALUES
(1,'Where is Malayalam University located and who can access the courses?','Malayalam University offers online courses accessible from anywhere in the world. Students, institutions, and cultural organizations can enroll and learn at their convenience.',1,'2026-01-12 09:07:27','2026-01-12 09:07:27',NULL),
(2,'What types of courses does Malayalam University provide?','The university offers a wide range of courses across multiple categories, including undergraduate, graduate, certified programs, and specialized cultural and religious studies.',1,'2026-01-12 09:07:27','2026-01-12 09:07:27',NULL),
(3,'How are the courses structured?','Courses are modular and include detailed attachments and resources. Students can learn at their own pace, completing modules whenever they are free.',1,'2026-01-12 09:07:27','2026-01-12 09:07:27',NULL),
(4,'Does Malayalam University provide certificates?','Yes, upon successful completion of a course, students receive certificates. These are issued through a secure verification system and can be downloaded or added to the student transcript.',1,'2026-01-12 09:07:27','2026-01-12 09:07:27',NULL),
(5,'What services and features are available for students and institutions?','Students can track progress, submit assignments, communicate with teachers, and access learning resources. Institutions can manage students, teachers, courses, and analytics, ensuring a complete academic and administrative experience.',1,'2026-01-12 09:07:27','2026-01-12 09:07:27',NULL);
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;
UNLOCK TABLES;

