(37,'9','App\\Models\\Course',24,'cb7a1d775e800fd1ee4049f7dca9e041eb9ba083','6967651c181be',60,1,307,899.00,0.00,'BDT','USD',1.00000000,899.00000000,899.00,1,'{\"id\":9,\"program_id\":\"5\",\"university_id\":\"19\",\"title\":\"The History of God\'s Names in the Bible\",\"subtitle\":\"From Elohim to Abba: A Historical, Linguistic, and Christological Investigation\",\"slug\":\"The-History-of-Gods-Names-in-the-Bible\",\"thumbnail\":\"300\",\"intro_video_type\":2,\"intro_video\":\"D9b9h5mCgAc\",\"duration\":\"42\",\"price\":\"899.00\",\"course_benefits\":[{\"name\":\"Critical Training\",\"value\":\"Advanced biblical and theological analysis\"},{\"name\":\"Bilingual Study\",\"value\":\"Malayalam & English\"}],\"start_date\":\"2026-01-31T00:00:00.000000Z\",\"description\":\"This seminar provides a forensic, historical, and linguistic investigation into the evolution of divine nomenclature in the biblical text. We move from the Bronze Age \'El\' to the nationalistic \'Yahweh\' of the iron age, concluding with the Christological \'Father.\' The course investigates the \\\"Alienation Hypothesis\\\": Did Jesus restore a universal, pre-redactional truth that was suppressed by post-exilic religious authorities?\",\"description_point\":[{\"title\":\"Philological Mastery\",\"text\":\"Distinguish between $Elohim$, $YHWH$, and $Pater$ in original contexts.\"},{\"title\":\"Redactional Analysis\",\"text\":\"Identify the 5th-century BCE motives of the Ezra group in merging divine attributes.\"},{\"title\":\"Cross-Cultural Synthesis:\",\"text\":\"Map the influence of Persian (Zoroastrian) dualism and Mesopotamian science on Jewish theology.\"},{\"title\":\"Christological Critique:\",\"text\":\"Evaluate Jesus\\u2019 rejection of Temple hierarchies and his use of \\\"Abba\\\" as a corrective to nationalistic Yahwism.\"}],\"faqs\":[{\"question\":\"Who can enroll in this course?\",\"answer\":\"Graduate students, theology scholars, clergy, and advanced learners with interest in biblical history and linguistics.\"},{\"question\":\"Is prior knowledge of Hebrew or Greek required?\",\"answer\":\"Is prior knowledge of Hebrew or Greek required?\"},{\"question\":\"What languages can assignments be submitted in?\",\"answer\":\"Malayalam or English (SBL academic style).\"},{\"question\":\"Is this course fully online?\",\"answer\":\"Yes. All lectures, readings, and Socratic seminars are conducted online\"},{\"question\":\"What is the final assessment?\",\"answer\":\"A 20-page research-based synthesis paper defending a theological or historical thesis.\"}],\"instructors\":[{\"name\":\"To Be Announced\",\"professional_title\":\"Senior Lecturer in Biblical Studies\",\"photo\":\"301\"}],\"meta_title\":null,\"meta_description\":null,\"meta_keywords\":null,\"og_image\":null,\"created_by\":\"59\",\"status\":\"1\",\"deleted_at\":null,\"created_at\":\"2026-01-13T05:21:20.000000Z\",\"updated_at\":\"2026-01-13T05:30:45.000000Z\"}',NULL,'2026-01-14 09:43:31',1,59,NULL,'2026-01-14 04:12:52','2026-01-14 04:13:31'),
