(47,'12','App\\Models\\Course',2,NULL,'6989cdeea5086',60,NULL,NULL,100.00,0.00,'BDT','USD',1.00000000,100.00000000,100.00,1,'{\"id\":12,\"level_id\":3,\"subject_id\":2,\"program_id\":6,\"university_id\":19,\"department_id\":1,\"sub_department_id\":1,\"title\":\"The Documentary Hypothesis (Pentateuchal Studies)\",\"subtitle\":\"A non-faith-based analysis of the first five books\",\"subject_title\":\"Biblical Studies\",\"course_code\":\"BIBL150\",\"slug\":\"The-Documentary-Hypothesis-Pentateuchal-Studies\",\"thumbnail\":\"335\",\"intro_video_type\":2,\"intro_video\":\"KFp8n5tqsRU\",\"duration\":1,\"credit_hours\":\"3.00\",\"prerequisite\":null,\"price\":\"100.00\",\"course_benefits\":[{\"name\":\"Critical Analysis\",\"value\":\"Understand the historical compilation of the Pentateuch\"},{\"name\":\"Textual Comparison\",\"value\":\"Compare different manuscript traditions\"}],\"start_date\":\"2026-02-01T00:00:00.000000Z\",\"description\":\"A non-faith-based analysis of the first five books. Investigates the theory that four distinct scribal groups (J, E, D, P) compiled these texts over centuries.\",\"description_point\":[{\"title\":\"Pentateuchal Sources\",\"text\":\"Learn to identify J, E, D, P source material in the text\"},{\"title\":\"Historical Context\",\"text\":\"Study the socio-political reasons behind textual compilation\"}],\"faqs\":[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate students in Religious Studies and Biblical Studies\"}],\"instructors\":[{\"name\":\"To be announced\",\"professional_title\":\"Professor of Biblical Studies\",\"photo\":\"322\"}],\"meta_title\":null,\"meta_description\":null,\"meta_keywords\":null,\"og_image\":null,\"created_by\":59,\"status\":1,\"intake_status\":1,\"deleted_at\":null,\"created_at\":\"2026-01-15T00:30:00.000000Z\",\"updated_at\":\"2026-01-15T02:49:26.000000Z\"}',NULL,NULL,0,NULL,NULL,'2026-02-09 12:07:10','2026-02-09 12:07:10'),
(48,'12','App\\Models\\Course',2,NULL,'6989cdff32896',60,NULL,NULL,100.00,0.00,'BDT','USD',1.00000000,100.00000000,100.00,1,'{\"id\":12,\"level_id\":3,\"subject_id\":2,\"program_id\":6,\"university_id\":19,\"department_id\":1,\"sub_department_id\":1,\"title\":\"The Documentary Hypothesis (Pentateuchal Studies)\",\"subtitle\":\"A non-faith-based analysis of the first five books\",\"subject_title\":\"Biblical Studies\",\"course_code\":\"BIBL150\",\"slug\":\"The-Documentary-Hypothesis-Pentateuchal-Studies\",\"thumbnail\":\"335\",\"intro_video_type\":2,\"intro_video\":\"KFp8n5tqsRU\",\"duration\":1,\"credit_hours\":\"3.00\",\"prerequisite\":null,\"price\":\"100.00\",\"course_benefits\":[{\"name\":\"Critical Analysis\",\"value\":\"Understand the historical compilation of the Pentateuch\"},{\"name\":\"Textual Comparison\",\"value\":\"Compare different manuscript traditions\"}],\"start_date\":\"2026-02-01T00:00:00.000000Z\",\"description\":\"A non-faith-based analysis of the first five books. Investigates the theory that four distinct scribal groups (J, E, D, P) compiled these texts over centuries.\",\"description_point\":[{\"title\":\"Pentateuchal Sources\",\"text\":\"Learn to identify J, E, D, P source material in the text\"},{\"title\":\"Historical Context\",\"text\":\"Study the socio-political reasons behind textual compilation\"}],\"faqs\":[{\"question\":\"Who can enroll?\",\"answer\":\"Undergraduate students in Religious Studies and Biblical Studies\"}],\"instructors\":[{\"name\":\"To be announced\",\"professional_title\":\"Professor of Biblical Studies\",\"photo\":\"322\"}],\"meta_title\":null,\"meta_description\":null,\"meta_keywords\":null,\"og_image\":null,\"created_by\":59,\"status\":1,\"intake_status\":1,\"deleted_at\":null,\"created_at\":\"2026-01-15T00:30:00.000000Z\",\"updated_at\":\"2026-01-15T02:49:26.000000Z\"}',NULL,NULL,0,NULL,NULL,'2026-02-09 12:07:27','2026-02-09 12:07:27'),
(49,'11','App\\Models\\Course',2,NULL,'6989ce1739339',60,NULL,NULL,100.00,0.00,'BDT','USD',1.00000000,100.00000000,100.00,1,'{\"id\":11,\"level_id\":3,\"subject_id\":3,\"program_id\":6,\"university_id\":19,\"department_id\":null,\"sub_department_id\":null,\"title\":\"History of the Biblical Canon\",\"subtitle\":\"How the Biblical Texts Were Selected and Preserved\",\"subject_title\":null,\"course_code\":null,\"slug\":\"History-of-the-Biblical-Canon\",\"thumbnail\":\"333\",\"intro_video_type\":2,\"intro_video\":\"DDJI_f8bTUM\",\"duration\":1,\"credit_hours\":\"3.00\",\"prerequisite\":null,\"price\":\"100.00\",\"course_benefits\":[{\"name\":\"Historical Insight\",\"value\":\"Gain a deeper understanding of the origins of the biblical canon\"},{\"name\":\"Analytical Skills\",\"value\":\"Develop critical thinking through historical evaluation of texts\"},{\"name\":\"Academic Readiness\",\"value\":\"Prepare for advanced studies in theology and religious history\"}],\"start_date\":\"2026-01-30T00:00:00.000000Z\",\"description\":\"A scientific study of the \\\"Selection Process.\\\" This course examines why certain books were excluded (Apocrypha\\/Gnostics) and how institutional councils finalized the list based on political and social needs.\",\"description_point\":[{\"title\":\"Canon Formation\",\"text\":\"Understand how and why biblical books were selected or excluded.\"},{\"title\":\"Apocrypha & Gnostic Texts\",\"text\":\"Study non-canonical writings and their significance\"},{\"title\":\"Councils & Authority\",\"text\":\"Understand how councils and institutions shaped the canon\"}],\"faqs\":[{\"question\":\"Who should take this course?\",\"answer\":\"Undergraduate students interested in biblical history and textual studies.\"},{\"question\":\"Is this course faith-based or academic?\",\"answer\":\"The course follows an academic and historical approach.\"},{\"question\":\"Will non-canonical texts be studied?\",\"answer\":\"Yes, the Apocrypha and Gnostic writings are key topics.\"}],\"instructors\":[{\"name\":\"To be announced\",\"professional_title\":\"Senior Lecturer of History of the Biblical Canon\",\"photo\":\"320\"}],\"meta_title\":null,\"meta_description\":null,\"meta_keywords\":null,\"og_image\":null,\"created_by\":59,\"status\":1,\"intake_status\":1,\"deleted_at\":null,\"created_at\":\"2026-01-15T00:20:04.000000Z\",\"updated_at\":\"2026-01-16T04:04:59.000000Z\"}',NULL,NULL,0,NULL,NULL,'2026-02-09 12:07:51','2026-02-09 12:07:51'),
