INSERT INTO `programs` VALUES
(5,19,'General','General','{\"title\":\"Biblical Studies Graduate Program\",\"details\":\"<p>This program introduces students to the historical, linguistic, and theological study of biblical texts. Designed for graduate-level learners, it offers flexible online modules and research-oriented projects for a comprehensive learning experience.<\\/p>\",\"image\":295}','{\"title\":\"Program Overview\",\"details\":\"<p>Students explore the basics of Hebrew, Greek, and Aramaic to understand the original texts of the Bible. Practical exercises help build reading and interpretation skills.<\\/p>\",\"image\":296}',61,3,NULL,'2026-01-12 05:17:09','2026-01-30 07:38:12'),
(6,19,'Bible Courses','Bible-Courses','{\"title\":\"Bible Study Program\",\"details\":\"<p data-start=\\\"323\\\" data-end=\\\"623\\\">This program provides structured Bible courses focused on reading, understanding, and interpreting Scripture. The courses are designed for individuals who want to study the Bible in an organized and guided manner. Content includes selected passages, explanations, and study references.<\\/p>\",\"image\":311}','{\"title\":\"Course Structure\",\"details\":\"<p>The program is divided into steps that follow a logical learning sequence. Each step includes assigned readings, lesson notes, and review activities. Participants move through the steps at a steady pace to build a clear understanding of biblical texts and themes.<\\/p>\",\"image\":312}',59,1,NULL,'2026-01-15 00:00:13','2026-01-15 00:00:13'),
(7,19,'Performing Arts','Performing-Arts','{\"title\":\"Performing Arts Program\",\"details\":\"<p>This program focuses on the study and practice of performing arts, including music, dance, and drama. It is designed to provide participants with foundational knowledge, technical skills, and practical experience through structured lessons and guided activities.<\\/p>\",\"image\":315}','{\"title\":\"Program Structure\",\"details\":\"<p>The program is organized into step-based modules that progress from basic concepts to more advanced techniques. Each step includes practice exercises, instructional guidance, and performance activities to support skill development and consistent learning.<\\/p>\",\"image\":316}',59,1,NULL,'2026-01-15 00:02:35','2026-01-15 00:02:35'),
(8,19,'Certified Programs','Certified-Programs','{\"title\":\"Certification-Based Programs\",\"details\":\"<p>This program includes certification-based courses designed to provide formal training in specific subject areas. The courses follow defined learning objectives and assessment criteria. Upon successful completion, participants receive certification acknowledging their acquired knowledge and skills.<\\/p>\",\"image\":317}','{\"title\":\"Certification Process\",\"details\":\"<p data-start=\\\"820\\\" data-end=\\\"1124\\\">The program is structured into sequential steps that include instruction, practice, and evaluation. Each step must be completed according to program requirements. Assessments are used to measure progress, and certification is issued only after all required steps are successfully finished.<\\/p>\",\"image\":318}',59,1,NULL,'2026-01-15 00:04:26','2026-01-15 00:04:26');
/*!40000 ALTER TABLE `programs` ENABLE KEYS */;
UNLOCK TABLES;

