pt 9pt 6pt 9pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"line-height:1.38;margin-top:0pt;margin-bottom:24pt;\"><span style=\"font-size:11pt;font-family:Arial,sans-serif;color:#1f1f1f;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">80 hours of high-level community service.</span></p></td><td style=\"border-left:solid #1f1f1f 0.58685475pt;border-right:solid #1f1f1f 0.58685475pt;border-bottom:solid #1f1f1f 0.58685475pt;border-top:solid #1f1f1f 0.58685475pt;vertical-align:top;padding:6pt 9pt 6pt 9pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"line-height:1.38;margin-top:0pt;margin-bottom:24pt;\"><span style=\"font-size:11pt;font-family:Arial,sans-serif;color:#1f1f1f;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">2 Credits</span></p></td></tr><tr style=\"height:41.25pt\"><td style=\"border-left:solid #1f1f1f 0.58685475pt;border-right:solid #1f1f1f 0.58685475pt;border-bottom:solid #1f1f1f 0.58685475pt;border-top:solid #1f1f1f 0.58685475pt;vertical-align:top;padding:6pt 9pt 6pt 9pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"line-height:1.38;margin-top:0pt;margin-bottom:24pt;\"><span style=\"font-size:11pt;font-family:Arial,sans-serif;color:#1f1f1f;background-color:transparent;font-weight:700;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Max Service Credits</span></p></td><td style=\"border-left:solid #1f1f1f 0.58685475pt;border-right:solid #1f1f1f 0.58685475pt;border-bottom:solid #1f1f1f 0.58685475pt;border-top:solid #1f1f1f 0.58685475pt;vertical-align:top;padding:6pt 9pt 6pt 9pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"line-height:1.38;margin-top:0pt;margin-bottom