(11,'Bilingual Biblical Studies Program','Bilingual-Biblical-Studies-Program','<p>Our THEO-620 Bilingual Biblical Studies Program offers a structured 6-week intensive course designed for graduate students. We provide detailed module guidance, bilingual support (English &amp; Malayalam), and step-by-step assistance to help students complete all course requirements, submit assessments, and earn certification.</p>',NULL,'[{\"name\":\"Module Assistance\",\"value\":\"Support and guidance for all six modules from \\u201cThe Primal Elohim\\u201d to \\u201cChristological Synthesis\"},{\"name\":\"Bilingual Support\",\"value\":\"Materials and instruction available in both English and Malayalam for deeper understanding\"}]',100.00,'299','298',1,NULL,'2026-01-12 05:25:12','2026-01-12 05:25:12',19);
