INSERT INTO `testimonials` VALUES
(1,'Benjamin Harris',NULL,'Studylifter made my dream of studying abroad come true. Their team handled everything smoothly, from university selection to visa application.','66',0,'2024-11-02 23:31:51','2024-11-24 23:21:46',NULL),
(2,'Christopher Jordan',NULL,'I felt overwhelmed by the application process, but Studylifter guided me every step of the way. Highly recommend their services!','67',0,'2024-11-02 23:33:27','2024-11-02 23:33:27',NULL),
(3,'Ava White',NULL,'Their expertise in securing scholarships is incredible. I saved a lot of money and had the best study experience.','68',0,'2024-11-02 23:33:50','2024-11-24 23:21:37',NULL),
(4,'Emma Thomas',NULL,'Studylifters team was always available to answer my questions. They made my journey stress-free.','69',0,'2024-11-02 23:34:23','2024-11-24 23:21:24',NULL),
(5,'Emily Johnson',NULL,'Studylifters guidance and support were invaluable. Their team went above and beyond to ensure I felt confident and informed every step of the way.','135    ',0,'2024-11-02 23:34:23','2024-11-24 23:28:24',NULL),
(6,'Jhon Moragn',NULL,'Working with Studylifter was a fantastic experience. Their team was proactive, knowledgeable, and truly dedicated to helping me succeed.','222',1,'2024-11-02 23:34:23','2024-11-24 23:28:43',NULL),
(7,'Anjali Menon','2025-02-10','I really enjoyed the course on \"The History of God\'s Names in the Bible.\" The modules were clear, easy to follow, and I could study at my own pace. The bilingual lessons helped me understand both English and Malayalam perspectives.','281',1,'2026-01-12 09:15:33','2026-01-12 04:27:55',NULL),
(8,'Ravi Kumar','2025-03-05','The Malayalam University courses are very flexible. I could access the materials anytime and learn at my own speed. The assignments were helpful and practical.','280',1,'2026-01-12 09:15:34','2026-01-12 04:27:38',NULL),
(9,'Sofia Thomas','2025-04-12','I took a certification course here and found it very useful. The lessons are well-organized and easy to understand. I also liked that I could download the materials and revisit them whenever I needed.','279',1,'2026-01-12 09:15:34','2026-01-12 04:27:16',NULL),
(10,'Ajay Nair','2025-05-20','Studying at Malayalam University was convenient. The course modules were detailed but simple to follow, and I appreciated the step-by-step guidance and clear instructions.','278',1,'2026-01-12 09:15:34','2026-01-12 04:27:04',NULL),
(11,'Leena Mathew','2025-06-08','The courses are very well-structured and easy to access from anywhere. I liked the way lessons were split into modules, making learning less stressful and more enjoyable.','277',1,'2026-01-12 09:15:34','2026-01-12 04:26:49',NULL);
/*!40000 ALTER TABLE `testimonials` ENABLE KEYS */;
UNLOCK TABLES;

