INSERT INTO `universities` VALUES
(19,59,'Malayalam Univeristy','Malayalam-Univeristy','283','1','282',1,100,'<h2 data-start=\"267\" data-end=\"301\"><span style=\"font-size: 16px;\">Malayalam University is a digital-first academic institution focused on delivering structured education, cultural scholarship, and certification programs through a flexible and accessible learning model. The university serves students, educators, institutions, and organizations across regions, supporting both formal and continuing education.<br><br></span></h2><h3 data-start=\"648\" data-end=\"666\">Academic Focus</h3><p data-start=\"667\" data-end=\"962\">Malayalam University offers courses across multiple disciplines, including language studies, cultural heritage, theology, arts, and applied academic subjects. Programs are designed using modular frameworks, allowing learners to progress at their own pace while meeting defined academic outcomes.<br><br></p><h3 data-start=\"964\" data-end=\"984\">Course Structure</h3><p data-start=\"985\" data-end=\"1269\">All courses are organized into clearly defined modules with supporting materials such as readings, videos, assessments, and attachments. Programs may include undergraduate-level, graduate-level, and certificate-based offerings, depending on the academic scope and credit requirements.<br><br></p><h3 data-start=\"1271\" data-end=\"1298\">Flexible Learning Model</h3><p data-start=\"1299\" data-end=\"1546\">Courses are accessible online, enabling learners to study from anywhere and at times convenient to them. This model supports working professionals, international learners, and community-based organizations seeking structured educational resources.<br><br></p><h3 data-start=\"1548\" data-end=\"1575\">Certification &amp; Credits</h3><p data-start=\"1576\" data-end=\"1850\">Malayalam University provides certificates upon successful course completion. Where applicable, courses follow credit-hour frameworks and academic evaluation standards. Certification issuance follows a verified approval process to ensure academic integrity and authenticity.<br><br></p><h3 data-start=\"1852\" data-end=\"1896\">Support for Institutions &amp; Organizations</h3><p data-start=\"1897\" data-end=\"2166\">The platform supports educational institutions, cultural organizations, and religious bodies with tools for course delivery, learner management, analytics, and reporting. This allows partner organizations to manage academic programs efficiently within a unified system.<br><br></p><h3 data-start=\"2168\" data-end=\"2193\">Commitment to Quality</h3><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><p data-start=\"2194\" data-end=\"2431\">Malayalam University emphasizes academic clarity, transparency, and continuous improvement. Course content, assessments, and certification processes are designed to align with recognized academic practices and institutional requirements.</p>','[\"Structured Academic Programs\",\"Learn from Anywhere\",\"Modular Learning Design\",\"Recognized Certifications\",\"Academic Quality & Transparency\"]','[284,285,286,287,288]','[289,290,291,292]',1000,1,1,1,'2026-01-12 04:58:51','2026-01-12 05:09:28',NULL),
(20,65,'university N','university-N','511','1','510',12,12,'<p><b data-path-to-node=\"1\" data-index-in-node=\"0\">Crestwood University</b> is a prestigious institution known for its stunning <b data-path-to-node=\"1\" data-index-in-node=\"73\">neo-Gothic architecture</b> and a deep commitment to academic excellence. Nestled among rolling hills and ancient oak trees, the campus offers a serene yet intellectually vibrant environment</p>','[\"world class faculty\"]','[512]','[513,514]',1200,1,1,1,'2026-02-09 12:53:04','2026-02-09 13:03:05',NULL);
/*!40000 ALTER TABLE `universities` ENABLE KEYS */;
